\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 96v\endash 98v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 BENEDICTUS XII. PAPA}}\plain \f1\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 BULLA \u8218 \'82PASTOR BONUS DILIGENS\lquote }}\plain \f1\fs22 . >Tenor secunde littere.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 Benedictus episcopus, servus servorum dei, ad futuram rei memoriam. Pastor bonus diligens operosus et pervigil \u8230 \'85}}\plain \f1\fs22  \endash  \u8230 \'85 Datum Avinionensis xv kalendas julii, pontificatus nostri anno primo. \endash  Druck: Magnum Bullarium Romanum, Bd. 3,2, S. 201 ff.; CALMA Bd. 2,2, S. 189, Nr. 115.}

