\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 86r\endash 95v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 BENEDICTUS XII. PAPA}}\plain \f1\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 BULLA \u8218 \'82FULGENS SICUT STELLA MATUTINA\lquote }}\plain \f1\fs22 . >Incipiunt statuta domini Benedicti pape de reformatione ordinis Cysterciensis.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 Benedictus episcopus, servus servorum dei, ad perpetuam rei memoriam. Fulgens sicut stella matutina in medio nebule, sacer cysterciensis ordo in ecclesia militante strennue militat operibus et exemplis \u8230 \'85}}\plain \f1\fs22  \endash  \u8230 \'85 Datum apud Pontemsorgie [!] Avinionensis dyocesis, quarto idus julii, pontificatus nostri anno primo. \endash  Druck: Canivez, Statuta, Bd. 3, S. 410\endash 436; Magnum Bullarium Romanum, Bd. 3,2, S. 203\endash 213. CALMA Bd. 2,2, S. 188, Nr. 111. Anschlie\u223 \'dfend: BENEDICTUS XII. PAPA: BULLA \u8218 \'82REGULAREM VITAM\lquote . {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 Benedictus episcopus, servus servorum dei, ad perpetuam rei memoriam. Regularem vitam professis sic expedit subtrahi omnem inquietudinis et turbacionis materiam \u8230 \'85}}\plain \f1\fs22  \endash  \u8230 \'85 Datum Avinionensis iiii nonas julii, pontificatus nostri anno primo. \endash  Druck: Magnum Bullarium Romanum, Bd. 3,2, S. 203. CALMA Bd. 2,2, S. 189, Nr. 118.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset1 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 96r\endash 111v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 LIBELLUS NOVELLARUM DEFINITIONUM ORDINIS CISTERCIENSIS}}\plain \f1\fs22 . >Novelle statute.< >Incipit prologus novellorum statutorum ordinis cysterciensis.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 Ut statutorum cysterciensis ordinis scrutatores brevius inveniant, quod exoptant, diffiniciones ipsius ordinis capituli generalis ab anno domini Mmo ccc xvimo, quo diffinicionum libellus extitit compilatus usque ad annum quinquagesimum sub eisdem titulis, qui continentur in eodem \u8230 \'85}}\plain \f1\fs22  \endash  \u8230 \'85 per dictos patres abbates vel eciam reprobentur. \endash  Druck: Nomasticon Cisterciense S. 498\endash 536. Winter, Zisterzienser, Bd. 1, S. 299 (Hs. genannt); H. H\u228 \'e4rtel / F. Ekowski, Handschriften der Nieders\u228 \'e4chsischen Landesbibliothek Hannover, s. o., S. 71 (Hs. genannt).}

