\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 164r Exzerpte aus: [{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 LIBELLUS ANTIQUARUM DEFINITIONUM ORDINIS CISTERCIENSIS}}\plain \f1\fs22 ], dist. 7, cap. 2, 4, dist. 8, cap. 1, dist. 15, cap. 3, dist. 15, cap. 2 / [{\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 LIBER USUUM}}\plain \f1\fs22 ], cap. 16. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 Abbates et monachi atque moniales semel ad minus in ebdomada confiteantur \u8230 \'85}}\plain \f1\fs22  \endash  \u8230 \'85 vel cui ipse commiserit vices suas. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 Quilibet sacerdos, qui non habet ultimum impedimentum, tenetur ter celebrare missam in ebdomada \u8230 \'85}}\plain \f1\fs22  \endash  \u8230 \'85 et omnibus diebus, quibus fit sermo in capitulo. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 Novicii autem communicabunt in die natalis domini, cene, pasche et penthecostes \u8230 \'85}}\plain \f1\fs22  \endash  \u8230 \'85 super calicem dividat ministris communicaturis. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 Et sciendum quod tociens licet sacramentum de pixide mutare et renovare, quociens timetur corrode a vermibus \u8230 \'85}}\plain \f1\fs22  \endash  \u8230 \'85 reponantur in pixidem ad conservandas pro communicandis infirmis.}

