\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\fs22 2ra\endash 195vb {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 LEGENDAE SANCTORUM}}\plain \f2\fs22 .Die\plain \f1\expndtw45\lang1033\fs22  \plain \f2\fs22 vorliegende\plain \f1\expndtw45\lang1033\fs22  \plain \f2\fs22 Hs.\plain \f1\expndtw45\lang1033\fs22  \plain \f2\fs22 \u252 \'fcberliefert\plain \f1\expndtw45\lang1033\fs22  \plain \f2\fs22 eine\plain \f1\charscalex99\expndtw90\lang1033\fs22  \plain \f2\fs22 Sammlung von Legenden, die aus verschiedenen Quellen stammen. Zahlreiche Texte konnten in der \u8222 \'84Legenda aurea\ldblquote  (\plain \f1\b\lang1033\fs22 LA\plain \f2\fs22 ) und im Martyrologium von\plain \f1\charscalex99\expndtw60\lang1033\fs22  \plain \f2\fs22 Ado\plain \f1\expndtw30\lang1033\fs22  \plain \f2\fs22 Viennensis\plain \f1\expndtw30\lang1033\fs22  \plain \f2\fs22 (\plain \f1\b\lang1033\fs22 Ado,\plain \f1\b\expndtw30\lang1033\fs22  \plain \f1\b\lang1033\fs22 Mart.\plain \f2\fs22 )\plain \f1\expndtw30\lang1033\fs22  \plain \f2\fs22 nachgewiesen\plain \f1\expndtw30\lang1033\fs22  \plain \f2\fs22 werden.\plain \f1\expndtw30\lang1033\fs22  \plain \f2\fs22 Die\plain \f1\expndtw30\lang1033\fs22  \plain \f2\fs22 Kapitelangaben\plain \f1\charscalex99\expndtw90\lang1033\fs22  \plain \f2\fs22 zur \u8222 \'84Legenda aurea\ldblquote  folgen der Ausgabe von Maggioni, Legenda aurea. Die\plain \f1\charscalex99\expndtw60\lang1033\fs22  \plain \f2\fs22 hier\plain \f1\expndtw30\lang1033\fs22  \plain \f2\fs22 vorliegenden\plain \f1\expndtw30\lang1033\fs22  \plain \f2\fs22 Legenden\plain \f1\expndtw30\lang1033\fs22  \plain \f2\fs22 stellen\plain \f1\expndtw30\lang1033\fs22  \plain \f2\fs22 meistens\plain \f1\expndtw30\lang1033\fs22  \plain \f2\fs22 eine\plain \f1\expndtw30\lang1033\fs22  \plain \f2\fs22 Kurzfassung\plain \f1\expndtw30\lang1033\fs22  \plain \f2\fs22 oder\plain \f1\expndtw30\lang1033\fs22  \plain \f2\fs22 Bearbeitung gegen\u252 \'fcber der o.g