].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Marcus vero a beato Petro Alexandrinam }}{\field{\*\fldinst HYPERLINK "hida://5650[33].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[33].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  est missus \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 LA 57; (59va\endash 60ra) \plain \f1\i\lang1033\fs22 De sancto Vitale. {\field{\*\fldinst HYPERLINK "hida://5650[34].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Natalis sancti Vitalis martyris, patris beatorum martyrum Gervasii et Prothasii, apud Ravennam colitur et cunctorum passim christi fidelium ore laudatur, qui militans cum Paulino iudice Ravennam est ingressus \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Text zum gro\u223 \'dfen Teil \u252 \'fcbereinstimmend mit Ado, Mart. (28. Apr.), PL 123, Sp. 252 f., und \u252 \'fcberliefert auch in Ms. C 6, 327ra\endash b; (60ra\endash rb)\plain \f1\i\lang1033\fs22  De sancto Quirino. {\field{\*\fldinst HYPERLINK "hida://5650[35].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rome sancti Quirini, tribuni et martyris, sub Traiano imperatore, qui cum ex precepto et beatum Allexandrum papam et Hermem prefectum in vincula coniecisset \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (30. M\u228 \'e4rz), PL 123, Sp. 243 f.; (59rb\endash va)\plain \f1\i\lang1033\fs22  De sancto Philippo\plain \f2\fs22 . LA 62; (60va\endash 61rb)\plain \f1\i\lang1033\fs22  De sancto Jacobo\plain \f2\fs22 . LA 63; (61rb\endash 62rb)\plain \f1\i\lang1033\fs22  De inventione sancte crucis\plain \f2\fs22 . LA 64; (62rb\endash va)\plain \f1\i\lang1033\fs22  De sancta Balbina. {\field{\*\fldinst HYPERLINK "hida://5650[36].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rome sancte Balbine virginis, filie Quirini martyris. Qui beatus martyr tollens boiam de collo Allexandri pape \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (31. M\u228 \'e4rz), PL 123, Sp. 244; (62va\endash 63ra)\plain \f1\i\lang1033\fs22  De sancto Iohanne ante portam latinam\plain \f2\fs22 . LA 65; (63ra)\plain \f1\i\lang1033\fs22  De sancto Gordiano\plain \f2\fs22 . LA 69; (63rb\endash vb)\plain \f1\i\lang1033\fs22  De sanctis Nereo et Achilleo\plain \f2\fs22 . LA 70; (63vb\endash 64rb)\plain \f1\i\lang1033\fs22  De sancto Pancracio\plain \f2\fs22 . LA 71; (64rb\endash vb)\plain \f1\i\lang1033\fs22  De sancto Allexandro, Evencio etc. {\field{\*\fldinst HYPERLINK "hida://5650[37].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rome sanctorum martyrum Alexandri pape, Evencii et Theodoli presbiterorum sub Traiano principe, iudice Aureliano, celebratur natalis. Qui Alexander episcopatum romane ecclesie tenuit \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (3. Mai), PL 123, Sp. 259 f.; (64vb\endash 66ra)\plain \f1\i\lang1033\fs22  De sancto Servacio. {\field{\*\fldinst HYPERLINK "hida://5650[38].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Servacius ex parentela salvatoris nostri Ihesu Christi secundum carnem ortum habuit. Anna enim et Esmeria sorores errant iuxta legem Moysi facte \u8230 \'85}}\plain \f2\fs22 ; (66ra\endash vb)\plain \f1\i\lang1033\fs22  De sancto Victore\plain \f2\fs22 . BHL Nr. 8561; (66vb\endash 67ra)\plain \f1\i\lang1033\fs22  De sancta Potenciana. {\field{\*\fldinst HYPERLINK "hida://5650[39].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rome sancte Potenciane virginis, que illustrissimi generis \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (19. Mai), PL 123, Sp. 268; (67ra\endash b)\plain \f1\i\lang1033\fs22  De sancto Urbano\plain \f2\fs22 . LA 72; (67ra\endash vb)\plain \f1\i\lang1033\fs22  De Venerabili Beda\plain \f2\fs22 . BHL Nr. 1075; (67vb\endash 68ra)\plain \f1\i\lang1033\fs22  De sancto Maximino. {\field{\*\fldinst HYPERLINK "hida://5650[40].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Maximinus urbis Equitanie }}{\field{\*\fldinst HYPERLINK "hida://5650[40].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[40].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  Pictavorum indigena clarissimis est ortus natalibus fratrem habens Maxencium, qui nobiliter educati a parentibus, sacris pariter litteris instruebantur \u8230 \'85}}\plain \f2\fs22 ; (68ra\endash b)\plain \f1\i\lang1033\fs22  De sancta Petronilla\plain \f2\fs22 . LA 73; (68rb\endash 69ra)\plain \f1\i\lang1033\fs22  De sanctis Marcellino et Petro. {\field{\*\fldinst HYPERLINK "hida://5650[41].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rome Marcellini presbyteri et Petri exorciste sub Dyocleciano, iudice Sereno \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (2. Juni), PL 123, Sp. 273 f.; (69ra\endash 70ra)\plain \f1\i\lang1033\fs22  De sancto Erasmo. {\field{\*\fldinst HYPERLINK "hida://5650[42].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 In Anthiocia }}{\field{\*\fldinst HYPERLINK "hida://5650[42].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[42].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  civitate facta est persecucio christianorum a Diocleciano imperatore \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 vgl. Th. Graesse (Hg.), Jacobus de Voragine: Legenda aurea, [Breslau] 1890 (Neudr. Osnabr\u252 \'fcck 1965), Kap. 199/196; (70ra\endash vb)\plain \f1\i\lang1033\fs22  De sancto Bonifacio. {\field{\*\fldinst HYPERLINK "hida://5650[43].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Cum enim primevo puerilis etatis multa }}{\field{\*\fldinst HYPERLINK "hida://5650[43].5666l/?u"}{\fldrslt \plain \f2\fs22\chcbpat17 [!] }}{\field{\*\fldinst HYPERLINK "hida://5650[43].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 decorare }}\plain \f2\fs22\chcbpat17 [!], {\field{\*\fldinst HYPERLINK "hida://5650[43].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 ut solet, materne sollicitudinis cura ablactatus atque enutritus esset\u8230 \'85}}\plain \f2\fs22 ; (70vb\endash ra)\plain \f1\i\lang1033\fs22  De sancto Medardo. {\field{\*\fldinst HYPERLINK "hida://5650[44].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 In Galliis, civitate Suessionis, nativitas sancti Medardi episcopi et confessoris. Qui ex claris parentibus ortum trahens patrem Nectardum nomine de genere Francorum habuit et matrem vero Protargiam nomineromanam \u8230 \'85}}\plain \f2\fs22 ; (71rb\endash vb)\plain \f1\i\lang1033\fs22  De sanctis Primo et Feliciano. {\field{\*\fldinst HYPERLINK "hida://5650[45].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rome in monte Celio nativitas sanctorum martyrum Primi et Feliciani sub Dyocleciano et Maximiano imperatoribus. Qui gloriosissimi martyres in domino semper viventes \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (9. Juni), PL 123, Sp. 282 f.; (71vb\endash 72rb)\plain \f1\i\lang1033\fs22  De sancto Maurino. {\field{\*\fldinst HYPERLINK "hida://5650[46].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Habemus, fratres karissimi, in oculis nostris testem fidei ydoneum catholice, Maurinum \u8230 \'85}}\plain \f2\fs22 ; (72rb\endash vb)\plain \f1\i\lang1033\fs22  De sancto Barnaba\plain \f2\fs22 . LA 76; (72vb\endash 73ra)\plain \f1\i\lang1033\fs22  De sanctis Nazario et Celso. {\field{\*\fldinst HYPERLINK "hida://5650[47].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Mediolano }}{\field{\*\fldinst HYPERLINK "hida://5650[47].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[47].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  nativitas sanctorum martyrum Nazarii et Celsi pueri. Beati Nazarii pater eius Africanus, mater vero Perpetua \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (12. Juni), PL 123, Sp. 285;(73ra\endash b)\plain \f1\i\lang1033\fs22  De sancta Felicula. {\field{\*\fldinst HYPERLINK "hida://5650[48].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rome sancte Felicule virginis et martyris. Quam cum Flaccus comes post decessum Petronille vellet ducere uxorem \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (13. Juni), PL 123, Sp. 285 f.; (73rb\endash vb)\plain \f1\i\lang1033\fs22  De sanctis Vito et Modesto etc\plain \f2\fs22 . LA 77; (73vb\endash 74ra)\plain \f1\i\lang1033\fs22  De sancto Basilio. {\field{\*\fldinst HYPERLINK "hida://5650[49].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Apud Cesaream Capadocie sancti Basilii episcopi, fratris sancti Gregorii et Petri. Qui cum esset omnibus virtutibus fundatus \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (14. Juni), PL 123, Sp. 286 f.; (74ra\endash va)\plain \f1\i\lang1033\fs22  De sancto Quirico\plain \f2\fs22 . LA 78; (74va\endash 75rb)\plain \f1\i\lang1033\fs22  De sanctis Marcelliano et Marco. {\field{\*\fldinst HYPERLINK "hida://5650[50].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Clarissimis viris Marcelliano et Marco, geminis fratribus, cotidie solacium prestit beatus Sebastianus \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 BHL Nr. 5302 (Bearbeitung); (75rb\endash va)\plain \f1\i\lang1033\fs22  De sanctis Gervasio et Prothasio. Post passionem beatissimi martyris Vitalis eiusque uxoris Valerie duo filii eorum Gervasius et Protasius domos resque parentum hereditates Mediolanis inhabitabant \u8230 \'85 \plain \f2\fs22 LA 80; (75va\endash 76vb)\plain \f1\i\lang1033\fs22  De sancto Albano\plain \f2\fs22 . BHL Nr. 8111; (76vb\endash 77ra)\plain \f1\i\lang1033\fs22  De sancto Albino. {\field{\*\fldinst HYPERLINK "hida://5650[51].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 In Britania sancti Albini martyris, qui tempore Dyocleciani in Verolamio civitate post verbera et tormenta acerba capite plexus est \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (22. Juni), PL 123, Sp. 290; (77ra\endash 77va)\plain \f1\i\lang1033\fs22  De decem milibus martyrum. {\field{\*\fldinst HYPERLINK "hida://5650[52].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Reverendissima et inextinguibilis memorie dignitas et passionis series et rigiditas sanctorum decem milium martirum veneracionis obsequio colitur decimo kalendas julii, inter quos domino precelsi et emeriti pullularunt videlicet Marcus et Allexander \u8230 \'85}}\plain \f2\fs22 ; (77va\endash 78vb)\plain \f1\i\lang1033\fs22  De sancto Johanne Baptista\plain \f2\fs22 . LA 81; (78vb\endash 79rb)\plain \f1\i\lang1033\fs22  De sancto Lebuino. Beatus Lebuinus in infancia sua sacris litterarum studiis a parentibus suis traditus est erudiendus \plain \f2\fs22 \u8230 \'85; (79rb\endash 80va)\plain \f1\i\lang1033\fs22  De sanctis Johanne et Paulo\plain \f2\fs22 . LA 82; (80va\endash 82rb)\plain \f1\i\lang1033\fs22  De septem dormientibus\plain \f2\fs22 . LA 97; (82rb\endash vb)\plain \f1\i\lang1033\fs22  De sancto Leone\plain \f2\fs22 . LA 83; (82vb\endash 83vb) \plain \f2\i\fs22 De sancto Petro apostolo\plain \f2\fs22 . LA 84; (83vb\endash 85ra)\plain \f1\i\lang1033\fs22  De sancto Paulo\plain \f2\fs22 . LA 85; (85ra\endash va)\plain \f1\i\lang1033\fs22  De sanctis Processi et Martiniani. {\field{\*\fldinst HYPERLINK "hida://5650[53].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rome nativitas sanctorum Processi et Martiniani tempore, quo Nero Christi apostolos tradidit Paulino nobili viro, scilicet Petrum et Paulum \u8230 \'85}}\plain \f2\fs22 ; (85va\endash 87ra) [BONIFATIUS IX. PAPA: BULLA DE FESTO VISITATIONIS BEATAE MARIAE CELEBRANDO], 9. November 1389.\plain \f1\i\lang1033\fs22  De visitacione beate Marie. {\field{\*\fldinst HYPERLINK "hida://5650[54].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Bonifacius episcopus, servus servorum dei, ad perpetue }}{\field{\*\fldinst HYPERLINK "hida://5650[54].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[54].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  rei memoriam. Superni benignitas conditoris \u8230 \'85}}\plain \f1\i\lang1033\fs22   \endash  \u8230 \'85 Datum Rome apud sanctum Petrum, quinto ydus novembris, pontificatus nostri anno primo\plain \f2\fs22 . \endash  Druck: Magnum Bullarium Romanum, Bd. 3,1, S. 378 f.; (87ra\endash 88ra)\plain \f1\i\lang1033\fs22  De sanctis virginibus Fide, Spe et Caritate. {\field{\*\fldinst HYPERLINK "hida://5650[55].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rome passio trium virginum: Fidei, Spei et Caritatis. Tempore Adriani imperatoris mulier quedam nobilis nomine Sophya cum tribus filiabus suis adveniens Romam \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 vgl. BHL Nr. 2971; (88ra\endash 89rb)\plain \f1\i\lang1033\fs22  De sancto Udelrico. {\field{\*\fldinst HYPERLINK "hida://5650[56].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Udelricus ex nobilibus parentibus secundum seculum et fidelibus secundum Christum \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 vgl. BHL (Novum Suppl.) Nr. 8366b; (89rb\endash vb) \u220 \'dcberschrift:\plain \f1\i\lang1033\fs22  De sancto Willibaldo\plain \f2\fs22 ; Text fehlt; (90ra\endash va)\plain \f1\i\lang1033\fs22  De sancto Kyliano\plain \f2\fs22 . BHL Nr. 4660; (90va\endash b)\plain \f1\i\lang1033\fs22  De sancto Agillolpho. {\field{\*\fldinst HYPERLINK "hida://5650[57].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Agillolphus, archiepiscopus Coloniensis, defuncto Pippino, Francorum rege, filium eius, Karolum, in regno succedentem\u8230 \'85}}\plain \f2\fs22 ; (90vb\endash 91ra)\plain \f1\i\lang1033\fs22  De septem fratribus\plain \f2\fs22 . LA 86; (91ra\endash 92rb)\plain \f1\i\lang1033\fs22  De translacione sancti Benedicti. {\field{\*\fldinst HYPERLINK "hida://5650[58].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Translacio sancti Benedicti facta est tempore Deodati pape, qui presedit apostolice sedi circa annum domini cc lxxi \u8230 \'85}}\plain \f2\fs22 ; (92rb\endash 93vb)\plain \f1\i\lang1033\fs22  De sanctis Felice et Nabore\plain \f2\fs22 . BHL Nr. 6029; CPL Nr. 2212; (93vb\endash 94vb)\plain \f1\i\lang1033\fs22  De sancta Margareta\plain \f2\fs22 . LA 89; (94vb\endash 96rb) SERMO DE DIVISIONE APOSTOLORUM.\plain \f1\i\lang1033\fs22  De divisione apostolorum. {\field{\*\fldinst HYPERLINK "hida://5650[59].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Gloriosissimos christiane fidei principes, apostolos, annuis solempnitatibus honorantes,fratres karissimi,ipsum dominum ac deum nostrum, qui huius auctor est fidei, debitare ligione veneremur\u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 dampnari meruebant\plain \f2\fs22 . Anfang wie PL 58, Sp. 880\endash 883 (Ps. Faustus Rhegiensis: Sermo de natali sancti Petri) und PL 57, Sp. 391\endash 396 (Ps. Maximus Taurinensis: Homilia innatali apostolorum Petri et Pauli I); vgl. CPPM Bd. 1, Nr. 4746; (96rb\endash vb)\plain \f1\i\lang1033\fs22  De sancto Alexio. {\field{\*\fldinst HYPERLINK "hida://5650[60].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Erat quidam vir tempore Archadii et Honorii imperatorum deo devotus, Eufemianus nomine, et uxor Aglaes fidelissima }}{\field{\*\fldinst HYPERLINK "hida://5650[60].5666l/?u"}{\fldrslt \plain \f2\fs22\chcbpat17 (96va) }}{\field{\*\fldinst HYPERLINK "hida://5650[60].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 et timens deum, quibus unicus erat filius nomine Allexius \u8230 \'85}}\plain \f2\fs22 ; (96vb\endash 97rb)\plain \f1\i\lang1033\fs22  De sancto Arnulpho\plain \f2\fs22 .\plain \f1\i\lang1033\fs22  Beatus Arnulphus, de prosapia Francorum genitus, altus satis et nobilis parentibus atque opulentissimus in rebus seculi fuit, sed nobilior deinceps et \plain \f2\fs22 (97ra) \plain \f1\i\lang1033\fs22  sublimior in fide Christi permansit \u8230 \'85 \plain \f2\fs22 BHL Nr. 689 (Kurzfassung und Bearbeitung; ohne Prolog); CPL Nr. 2087; (97rb\endash 98rb)\plain \f1\i\lang1033\fs22  De sancto Arsenio\plain \f2\fs22 . LA 174; (98rb\endash va)\plain \f1\i\lang1033\fs22  De sancta Praxede. {\field{\*\fldinst HYPERLINK "hida://5650[61].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rome Praxedis virginis sancte. Hec cum sorore sua Potenciana \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (21. Juli), PL 123, Sp. 304 f. (Text erweitert); (98va\endash 99rb)\plain \f1\i\lang1033\fs22  De sancta Maria Magdalena. {\field{\*\fldinst HYPERLINK "hida://5650[62].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Maria }}\plain \f1\i\lang1033\fs22\chcbpat17 Magdalena, a Magdalo castello {\field{\*\fldinst HYPERLINK "hida://5650[62].5666l/?u"}{\fldrslt \plain \f2\fs22\chcbpat17 (98vb) }}{\field{\*\fldinst HYPERLINK "hida://5650[62].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 sic dicta, nobilitate et diviciis et pulchritudine famosa,fren apud icicie in iuventute laxabat, audiens Ihesum propiciatorem in domo Symonis convivari \u8230 \'85}}\plain \f2\fs22 ; (99rb\endash 100rb)\plain \f1\i\lang1033\fs22  De translatione trium regum. {\field{\*\fldinst HYPERLINK "hida://5650[63].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Post annum ab incarnacione domini trecentesimum quartum, cum fides catholica floreret per universa orbis terrarum confinia, beata Helena, mater imperatoris Constantini, christianissima regina, cruce dominica Iherosolimis inventa multa sanctorum loca visitans \u8230 \'85}}\plain \f2\fs22 ; (100rb\endash 101rb)\plain \f1\i\lang1033\fs22  De sancto Apollonari \plain \f2\fs22 [!]\plain \f1\i\lang1033\fs22 . {\field{\*\fldinst HYPERLINK "hida://5650[64].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Apud Ravennam nativitas sancti Apollinaris. Hic Rome ordinatus a beato Petro \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (23. Juli), PL 123, Sp. 305 ff.; (101rb\endash va)\plain \f1\i\lang1033\fs22  De sancto Liborio\plain \f2\fs22 . BHL (Novum Suppl.) Nr. 4914c. V. de Vry, Liborius \endash  Br\u252 \'fcckenbauer Europas. Die mittelalterlichen Viten und Translationsberichte. Mit einem Anhang der Manuscripta Liboriana, Paderborn (u.a.) 1997, S. 241 (Hs.genannt); (101va\endash 102va)\plain \f1\i\lang1033\fs22  De sancta Cristina\plain \f2\fs22 . LA 94; (102va\endash 104ra)\plain \f1\i\lang1033\fs22  De sancto Jacobo\plain \f2\fs22 . LA 95; (104ra\endash 105rb)\plain \f1\i\lang1033\fs22  De sancto Cristofero\plain \f2\fs22 . LA 96; (105rb\endash 107va)\plain \f1\i\lang1033\fs22  De sancta Anna\plain \f2\fs22 . BHL (Novum Suppl.) Nr. 483b (Incipit abweichend); (107va\endash 108rb)\plain \f1\i\lang1033\fs22  De sancto Hermolao. {\field{\*\fldinst HYPERLINK "hida://5650[65].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Aput Nicomediam civitatem nativitas sancti Hermolai presbiteri, cuius doctrina beatus Pantaleon ad fidem conversus est. Hic fuit in domo sua absconsus cum aliis christianis \u8230 \'85}}\plain \f2\fs22 ; (108rb\endash 110va)\plain \f1\i\lang1033\fs22  De sancto Panthaleone\plain \f2\fs22 . BHL Nr. 6436, Text \u252 \'fcberliefert auch in Ms. C 19, 151r; (110va\endash b)\plain \f1\i\lang1033\fs22  De sancto Felice\plain \f2\fs22 . LA 99 (Text erweitert); (110vb\endash 111ra)\plain \f1\i\lang1033\fs22  De sanctis Simplicii, Faustini et Beatricis\plain \f2\fs22 . LA 100; BHL Nr. 7791; (111rb\endash 112rb)\plain \f1\i\lang1033\fs22  De sancta Martha\plain \f2\fs22 . LA 101; BHL Nr. 5548; (112rb\endash vb)\plain \f1\i\lang1033\fs22  De sanctis Abdon et Senne. {\field{\*\fldinst HYPERLINK "hida://5650[66].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rome nativitas Abdoni et Sennes martyrum, subregulorum sub imperio Decii. Audiens Decius imperator Abdon et Sennes in Persida sanctorum corpora colligere \u8230 \'85}}\plain \f2\fs22 ; (112vb\endash 113vb) \plain \f1\i\lang1033\fs22 De sancto Germano\plain \f2\fs22 . LA 103; (113va\endash 114va) SERMO DE SANCTO PETRO AD VINCULA.\plain \f1\i\lang1033\fs22  De sancto Petro ad vincula. {\field{\*\fldinst HYPERLINK "hida://5650[67].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Dilectissimi, referendum est nobis, unde dies iste solempnis habeatur, non enim, ut quidam sanctus Petrus a vinculis est absolutus \u8230 \'85}}\plain \f2\fs22 ; (114va\endash 115rb)\plain \f1\i\lang1033\fs22  De sanctis Machabeis. {\field{\*\fldinst HYPERLINK "hida://5650[68].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Apud Antiochiam nativitas sanctorum Machabeorum, septem fratrum, cum matre sua christiana et Eleazaro sacerdote, qui pro observacione sue legis, cum carnes porcinas nollent commedere, gravia tormentorum genera sub Antiochio rege perpessisunt \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 LA 104 (stark erweitert); (115rb\endash 116rb)\plain \f1\i\lang1033\fs22  De sancto Stephano papa\plain \f2\fs22 . BHL Nr. 7846; (116rb\endash 117vb)\plain \f1\i\lang1033\fs22  De invencione sancti Stephani\plain \f2\fs22 . LA 108; (117vb\endash 118rb)\plain \f1\i\lang1033\fs22  De sancto Justino. {\field{\*\fldinst HYPERLINK "hida://5650[69].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Nativitas sancti Iustini martyris, qui passusest tempore Dyocleciani et Maximiani sub Rixionario }}{\field{\*\fldinst HYPERLINK "hida://5650[69].5666l/?u"}{\fldrslt \plain \f2\fs22\chcbpat17 [!] }}{\field{\*\fldinst HYPERLINK "hida://5650[69].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 preside. Pater eius Matheus vocabulo filii Iustinus et Justinianus, sed Justinus ortu carnali precesserat \u8230 \'85}}\plain \f2\fs22 ; (118rb\endash vb)\plain \f1\i\lang1033\fs22  De sancto Oswaldo. {\field{\*\fldinst HYPERLINK "hida://5650[70].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Beatus Oswaldus, Elifridi Nortimbriorum }}{\field{\*\fldinst HYPERLINK "hida://5650[70].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[70].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  gentilis regis filius, adopcione divina eterni regis hereditatem acquisivit \u8230 \'85}}\plain \f2\fs22 ; (118vb\endash 120rb)\plain \f1\i\lang1033\fs22  De sancto Dominico\plain \f2\fs22 . LA 109; (120rb\endash 121ra)\plain \f1\i\lang1033\fs22  De sancto Sixto\plain \f2\fs22 . BHL Nr. 7801; CPL Nr. 2219; (121ra\endash 122va)\plain \f1\i\lang1033\fs22  De sancta Afra\plain \f2\fs22 .BHL Nr. 108 (Schluss abweichend); (122va\endash 123ra) De sancto Donato. LA 111 (Text ca. bis zur H\u228 \'e4lfte \u252 \'fcbereinstimmend); (123ra\endash vb)\plain \f1\i\lang1033\fs22  De sancto Ciriaco et sociis suis\plain \f2\fs22 . BHL (Novum Suppl.) Nr. 2056b; (123vb\endash 124ra)\plain \f1\i\lang1033\fs22  De sancto Romano. {\field{\*\fldinst HYPERLINK "hida://5650[71].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rome sancti Romani martyris. Hic }}{\field{\*\fldinst HYPERLINK "hida://5650[71].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (124ra)}}{\field{\*\fldinst HYPERLINK "hida://5650[71].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  per verba Laurencii, dum in tormentis esset, credidit et beato Laurencio dixit \u8230 \'85}}\plain \f2\fs22 ; (124ra\endash 125ra)\plain \f1\i\lang1033\fs22  De sancto Laurencio. {\field{\*\fldinst HYPERLINK "hida://5650[72].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Sanctus Laurencius genere Hispanus apud sedem apostolicam beati Petri sub beato Sixto papa archidyaconatus fungebatur officio, pueritate innocentis, vite liberalitate, operum misericordie \u8230 \'85}}\plain \f2\fs22 ; (125ra\endash vb)\plain \f1\i\lang1033\fs22  De sancto Tyburcio. {\field{\*\fldinst HYPERLINK "hida://5650[73].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Natalis Tyburcii martyris Rome inter duos lauros agitur tercio ydus augusti. Hic fuit filius Cromacii, urbis prefecti \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Anfang wie Ado, Mart. (11. August), PL 123, Sp. 325; (125vb\endash 127ra)\plain \f1\i\lang1033\fs22  De sancta Clara\plain \f2\fs22 . BHL Nr. 1815 (Kurzfassung); (127ra\endash vb)\plain \f1\i\lang1033\fs22  De sancto Euplo\plain \f2\fs22 . BHL Nr. 2729; (127vb\endash 128va)\plain \f1\i\lang1033\fs22  De sancto Ypolito\plain \f2\fs22 . BHL Nr. 3961 (Schluss abweichend); vgl. auch LA, Kap. 114; CPL Nr. 2219; (128va\endash 129va)\plain \f1\i\lang1033\fs22  De sancto Eusebio\plain \f2\fs22 . LA 104; (129va\endash 132va)\plain \f1\i\lang1033\fs22  De assumpcione beate virginis Marie. {\field{\*\fldinst HYPERLINK "hida://5650[74].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Modus sacratissime assumptionis Marie traditur in quodam sermone ex diversis dictis sanctorum compilato \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 LA 115 (Exzerpt, mit Zus\u228 \'e4tzen aus anderen Quellen); (132va\endash 133ra)\plain \f1\i\lang1033\fs22  De sancta Helena. {\field{\*\fldinst HYPERLINK "hida://5650[75].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Constantino Augusto et Licinio Licini, Augusti filio Constantini, autem ex sorore nepote quater consulibus facta est congregacio Iudeorum et Christianorum in urbe romana}}{\field{\*\fldinst HYPERLINK "hida://5650[75].5666l/?u"}{\fldrslt \plain \f2\fs22\chcbpat17 \u8230 \'85}}\plain \f2\fs22 ; (133ra\endash vb)\plain \f1\i\lang1033\fs22  De sancto Agapito\plain \f2\fs22 .\plain \f1\i\lang1033\fs22  Apud Brunestiam \plain \f2\fs22 [!]\plain \f1\i\lang1033\fs22  civitatem, miliario ab urbe tricesimo quarto, natalis sancti Agapiti martyris sub Aureliano imperatore et preside Antiocho. Cum esset puer annorum quindecim timens deum et amore Christi martyrio ferveret omnibus suis rebus et seculo renunciavit \u8230 \'85 \plain \f2\fs22 BHL Nr. 125 (Bearbeitung); (133vb\endash 134vb)\plain \f1\i\lang1033\fs22  De sancto Magno\plain \f2\fs22 . BHL Nr. 5169; (134vb\endash 137ra)\plain \f1\i\lang1033\fs22  De sancto Bernhardo\plain \f2\fs22 . LA 116; (137ra\endash vb)\plain \f1\i\lang1033\fs22  De sanctis Tymotheo et Symphoriano. {\field{\*\fldinst HYPERLINK "hida://5650[76].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rome, vico Ostensi, nativitas sancti Thymothei martyris in cimiterio eiusdem. Hunc ab Antiochia venien temet Christum publice predicantem tempore persecucionis hospicio Silvester papa, ad huc iuvenis, eum suscepit \u8230 \'85}}\plain \f2\fs22 ; (137rb\endash vb) LA 118 (Symphorianus); (137vb\endash 138va)\plain \f1\i\lang1033\fs22  De sancto Apollinari. {\field{\*\fldinst HYPERLINK "hida://5650[77].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Apollinaris vero cum vidisset angelos loquentes \u8230 \'85}}\plain \f2\fs22 ; (138va\endash 140ra)\plain \f1\i\lang1033\fs22  De sancto Bartholomeo. {\field{\*\fldinst HYPERLINK "hida://5650[78].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Cum ingressus esset in Indiam, beatus Bartholomeus venit in templum, in quo erat ydolum Astaroth \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 LA 119 (Bearbeitung); (140ra\endash 141rb)\plain \f1\i\lang1033\fs22  De sancto Genesio\plain \f2\fs22 . BHL Nr. 3322; (141rb\endash va)\plain \f1\i\lang1033\fs22  De sanctis Hereneo et Habundio\plain \f2\fs22 .\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[79].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Hodie sanctorum martyrum Herenei et Habundi Rome celebratur natalis, qui sub Decio et Valeriano martirio coronati sunt. Hii qualiter ad martyrii coronam pervenerunt, breviter intimamus \u8230 \'85}}\plain \f2\fs22 ; (141va)\plain \f1\i\lang1033\fs22  De sancto Rufo martyre. {\field{\*\fldinst HYPERLINK "hida://5650[80].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Apud Capuam nativitas sancti Rufi martyris, quem docuit et baptizavit beatus Apollinaris \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 nur Anfang, identisch mit Ado, Mart. (27. August), PL 123, Sp. 338; (142ra\endash b)\plain \f1\i\lang1033\fs22  De sancta Sabina. {\field{\*\fldinst HYPERLINK "hida://5650[81].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Roma }}{\field{\*\fldinst HYPERLINK "hida://5650[81].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[81].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 , in Aventino, in opido Bendinensi, ad Arcum Faustini, sanctissime et illustrissime Sabine martyris \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (29. August), PL 123, Sp. 341 f.; (142rb\endash 143ra)\plain \f1\i\lang1033\fs22  De sancto Augustino. {\field{\*\fldinst HYPERLINK "hida://5650[82].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Augustinus ab Affrica oriundus omnium arcium liberalium disciplinis imbutus fuit \u8230 \'85}}\plain \f2\fs22 ; (143ra\endash vb)\plain \f1\i\lang1033\fs22  De sancto Hermete. {\field{\*\fldinst HYPERLINK "hida://5650[83].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Hodie eciam beatus Hermes migravit ad dominum, quem beatus Allexander pontifex et martyr, cum esset prefectus urbis Rome, convertit \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (28. August), PL 123, Sp. 339 f.; (143vb\endash 145rb) HONORIUS AUGUSTODUNENSIS: SPECULUM ECCLESIAE (SERMO DE DECOLLATIONE JOHANNIS BAPTISTAE).\plain \f1\i\lang1033\fs22  De decollacione Johannis Baptiste. {\field{\*\fldinst HYPERLINK "hida://5650[84].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Justus si morte preoccupatus fuerit \u8230 \'85 }}{\field{\*\fldinst HYPERLINK "hida://5650[84].5666l/?u"}{\fldrslt \plain \f2\fs22\chcbpat17 [Sap 4,7]. }}{\field{\*\fldinst HYPERLINK "hida://5650[84].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Sanctus Johannes, qui hic in valle lacrimarum magna pressura premebatur \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 nec in cor hominis ascendit \plain \f2\fs22 [I Cor 2,9]. \endash  Druck: PL 172, Sp. 997\endash 1000. Schneyer Bd. 2, S. 722, Nr. 40; (145rb\endash vb)\plain \f1\i\lang1033\fs22  De sanctis Felice et Adaucto.{\field{\*\fldinst HYPERLINK "hida://5650[85].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rome, via Ostiensi, miliario secundo ab urbe, beatissimorum martyrum Felicis et Adaucti \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (30. August), PL 123, Sp. 342 ff. BHL Nr. 2878; CPL Nr. 2190; Text\u252 \'fcberliefert auch in Ms. C 6, 327ra; (145rb\endash vb)\plain \f1\i\lang1033\fs22  De sancto Paulino. {\field{\*\fldinst HYPERLINK "hida://5650[86].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Treveris nativitas sancti Paulini episcopi et confessoris \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (31. August), PL 123, Sp. 344; anschlie\u223 \'dfend Raum freigelassen; (146ra\endash 147ra)\plain \f1\i\lang1033\fs22  De sancto Egidio\plain \f2\fs22 . LA 123; (147ra\endash b)\plain \f1\i\lang1033\fs22  De sancto Prisco \plain \f2\fs22 (Raum f\u252 \'fcr Text freigelassen); (147va\endash 148ra)\plain \f1\i\lang1033\fs22  De sancto Anthonino\plain \f2\fs22 . BHL Nr. 569; (148ra\endash b)\plain \f1\i\lang1033\fs22  De sancto Remaclo. {\field{\*\fldinst HYPERLINK "hida://5650[87].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Fuit in Britanie partibus vir omni veneracione dignus nomine Remaclus \u8230 \'85}}\plain \f2\fs22 ; (148rb\endash vb)\plain \f1\i\lang1033\fs22  De sancto Marcello\plain \f2\fs22 . BHL Nr. 5246(Kurzfassung); (148vb\endash 149va)\plain \f1\i\lang1033\fs22  De sancto Victorino. {\field{\*\fldinst HYPERLINK "hida://5650[88].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 In suburbano Rome beati Victorini martyris. Fuerunt autem duo fratres \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (5. Sept.), PL 123, Sp. 346 f.; (149va\endash 150ra)\plain \f1\i\lang1033\fs22  De sancto Magno\plain \f2\fs22 . BHL Nr. 5162 (Exzerpt);(150ra\endash va)\plain \f1\i\lang1033\fs22  De sancta Regina\plain \f2\fs22 . BHL Nr. 7092/93 (?) (ohne Prolog, Schluss abweichend); (150va\endash 151rb)\plain \f1\i\lang1033\fs22  De sancto Evorcio\plain \f2\fs22 . BHL (Novum Suppl.) Nr. 2800d; (151rb\endash 153ra) [PETRUS DAMIANI: SERMO IN NATIVITATE SANCTAE MARIAE], Exzerpt. \plain \f1\i\lang1033\fs22 De nativitate beate Marie virginis. {\field{\*\fldinst HYPERLINK "hida://5650[89].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Nativitas beatissime et intemerate genitricis dei, fratres karissimi, merito precipuum et singulare prebet hominibus gaudium \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 et custodiunt illud\plain \f2\fs22 . \endash  Ed.: CCCM 57, S. 265\endash 273; (153ra\endash 154vb)\plain \f1\i\lang1033\fs22  De sancto Adriano\plain \f2\fs22 . LA 128; (154vb\endash 155ra)\plain \f1\i\lang1033\fs22  De sancto Gorgonio. {\field{\*\fldinst HYPERLINK "hida://5650[90].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Passio sanctorum Dorothei et Gorgonii apud Nycomediam, sub Dyocleciano imperatore. Horum prior Dorotheus magister in officiis \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (9. Sept.), PL 123, Sp. 351; (155ra\endash 156ra)\plain \f1\i\lang1033\fs22  De sanctis Protho et Jacincto\plain \f2\fs22 . LA 130; (156ra\endash va)\plain \f1\i\lang1033\fs22  De sancto Materno. {\field{\*\fldinst HYPERLINK "hida://5650[91].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Post decessum sancti Valerii beatus Maternus pontificalem suscipiens apicem cepit per civitates et regiones veram fidem constanter predicare ad viam salutis assidua monicione provocare \u8230 \'85}}\plain \f2\fs22 ; (156va\endash 157vb)\plain \f1\i\lang1033\fs22  De exaltacione sancte crucis. {\field{\*\fldinst HYPERLINK "hida://5650[92].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Exaltacionem sancte crucis ecclesia recolit, per quam fidem plurimum fuit exaltata \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 per crucis vexillum refert electrum tropheum\plain \f2\fs22 . (157vb\endash 159rb)\plain \f1\i\lang1033\fs22  De sanctis Cornelio et Cipriano. {\field{\*\fldinst HYPERLINK "hida://5650[93].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rome, via Appia, in cimiterio Calixti, nativitas sancti Cornelii episcopi sub persecucione Decii cum presbyteris et dyaconibus \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (14. Sept.), PL 123, Sp. 353\endash 356; (159rb) \plain \f1\i\lang1033\fs22 De sancto Nicomede. {\field{\*\fldinst HYPERLINK "hida://5650[94].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Nativitas sancti Nycomedis martyris. Quem Flaccus comes, cum ad eum perlatum fuisset, quod corpus sancte virginis Felicule, quam ipse pro Christo punierat, sepelisset, fecit teneri \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (15. Sept.), PL 123, Sp. 357; (159rb\endash 160ra)\plain \f1\i\lang1033\fs22  De sancta Eufemia. {\field{\*\fldinst HYPERLINK "hida://5650[95].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 In Calcidonia, civitate Europe, Dyocleciano imperante, ad delacionem Apelliani iniquissimi tradita est Eufemia, Philofroni senatoris et Theodore religiose filie }}{\field{\*\fldinst HYPERLINK "hida://5650[95].5666l/?u"}{\fldrslt \plain \f2\fs22\chcbpat17 [!] \u8230 \'85}}\plain \f2\fs22 ; (160ra\endash va)\plain \f1\i\lang1033\fs22  De sanctis Lucia et Geminiano. {\field{\*\fldinst HYPERLINK "hida://5650[96].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Lucia triginta sex annis accusata a filio suo Erumpno }}{\field{\*\fldinst HYPERLINK "hida://5650[96].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[96].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 , quod christiana esset \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (16. Sept.), PL 123, Sp. 358 f. (Bearbeitung); BHL Nr. 4989; (160va\endash 161rb)\plain \f1\i\lang1033\fs22  De sancto Lamberto. {\field{\*\fldinst HYPERLINK "hida://5650[97].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Dyocesi Tungrensi, Leodio publica, nativitas sancti Lamberti, episcopi et martyris. Hic ex parentibus preclaris Traiectensi urbe natus et litteris sacris primo eruditus Theodardo, eiusdem urbis episcopo, traditur in lege dei instruendus \u8230 \'85}}\plain \f2\fs22 ; (161rb\endash va)\plain \f1\i\lang1033\fs22  De sancto Januario. {\field{\*\fldinst HYPERLINK "hida://5650[98].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Iniquissimus Tymotheus audiens opinionem sancti martyris Ianuarii eum sibi exhiberi iussit \u8230 \'85}}\plain \f2\fs22 ; (161va\endash 162vb)\plain \f1\i\lang1033\fs22  De sancto Matheo. {\field{\*\fldinst HYPERLINK "hida://5650[99].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Dominus Ihesus curam suorum gerens misit apostolum suum Matheum in Ethiopiam, in civitatem, que dicitur Nadaber, ubi rex erat nomine Eglippus. In qua civitate invenit duos magos, Zaroes et Arfaxat, qui dixerunt se deos esse \u8230 \'85}}\plain \f2\fs22 ; wahrscheinlich Kurzfassung von BHL Nr. 5690; (162vb\endash 163va)\plain \f1\i\lang1033\fs22  De sancto Mauricio et sociis eius. {\field{\*\fldinst HYPERLINK "hida://5650[100].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 In Galliis, civitate Seduno seu Octodro }}{\field{\*\fldinst HYPERLINK "hida://5650[100].5666l/?u"}{\fldrslt \plain \f2\fs22\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[100].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 , loco Agauno, sanctorum martirum Thebeorum Mauricii, Candidi, Victoris, Innocencii, Vitalis cum sociis eorum sex milibus sextentis et sexaginta sex, qui sub Maximiano passi pro Christo gloriosa passione mundum illustraverunt \u8230 \'85}}\plain \f2\fs22 ; (163va\endash b)\plain \f1\i\lang1033\fs22  De sancta Tecla. {\field{\*\fldinst HYPERLINK "hida://5650[101].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Tecla virgo de Yconio civitate nata est et a beato Petro instructa \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (23. Sept.), PL 123, Sp. 304 f.; BHL Nr. 8025; (164ra\endash vb)\plain \f1\i\lang1033\fs22  De sancto Firmino. {\field{\*\fldinst HYPERLINK "hida://5650[102].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Temporibus Dyocleciani et Maximiani imperatorum persequencium christianos erat vir nomine Firmus, fide et opera catholicus \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 BHL Nr. 3002 (Incipit abweichend); (164vb\endash 165va)\plain \f1\i\lang1033\fs22  De sanctis Cypriano et Justine. {\field{\*\fldinst HYPERLINK "hida://5650[103].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Nativitas sanctorum martyrum Cypriani et Iustine virginis, qui passi sunt sub Dyocleciano imperatore, iudice Etilmo \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (26. Sept.), PL 123, Sp. 365 ff.; (165va\endash 166va)\plain \f1\i\lang1033\fs22  De sanctis Cosma et Damiano\plain \f2\fs22 . LA 139; (166va\endash 167va)\plain \f1\i\lang1033\fs22  De sancto Wenzelao. {\field{\*\fldinst HYPERLINK "hida://5650[104].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Wenzelaus fuit filius Spitdinei }}{\field{\*\fldinst HYPERLINK "hida://5650[104].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[104].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 , ducis Bohemie, cui postmodum in ducatu succesit florens omni virtutum honestate \u8230 \'85}}\plain \f2\fs22 ; (167va\endash 168rb)\plain \f1\i\lang1033\fs22  De sancto Michaele. {\field{\*\fldinst HYPERLINK "hida://5650[105].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Michael, prepositus paradisi, quem honorant angelici cives. Hic cotidie pro ecclesia orat, animas sanctas recipit et perducit in paradisum \u8230 \'85}}\plain \f2\fs22 ; (168rb\endash 169ra)\plain \f1\i\lang1033\fs22  De sancto Jheronimo. Jeronimus, in Dalmacia a patre Eusebio natus, Rome vestem Christi suscepit. Discipulus Donati et Victoris liberalibus studiis floruit \u8230 \'85\plain \f2\fs22 ; (169ra\endash 169va)\plain \f1\i\lang1033\fs22  De sancto Remigio\plain \f2\fs22 . LA 143; (169va\endash 170rb)\plain \f1\i\lang1033\fs22  De sancto Leodegario\plain \f2\fs22 . LA 144; (170rb\endash 171rb) \plain \f1\i\lang1033\fs22 De sancto Germano. {\field{\*\fldinst HYPERLINK "hida://5650[106].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Apud Antissioderum nativitas sancti Germani episcopi, qui multis virtutibus doctrine et continencie clarus extitit \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (1. Okt.), PL 123, Sp. 371 ff.; (171ra\endash b) \plain \f1\i\lang1033\fs22 De duobus Ewaldis. {\field{\*\fldinst HYPERLINK "hida://5650[107].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Gloriosa sanctorum martyrum Ewaldorum memoria festiva replicacione celebris commendat nobis seriem sui natalis \u8230 \'85}}\plain \f2\fs22 ; (171rb\endash vb)\plain \f1\i\lang1033\fs22  De sancto Francisco\plain \f2\fs22 . LA 145; (171vb\endash 172rb)\plain \f1\i\lang1033\fs22  De sancto Marso. {\field{\*\fldinst HYPERLINK "hida://5650[108].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Gloriosam huius diei solempnitatem exultabilem nobis, fratres karissimi, beati confessoris Marsi commemoracio reddit \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Text teilweise \u252 \'fcbereinstimmend mit BHL (Novum Suppl.) Nr. 5544c; (172rb)\plain \f1\i\lang1033\fs22  De sancto Marco. {\field{\*\fldinst HYPERLINK "hida://5650[109].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Marcus papa tercius, nacione romanus, ex patre Prisco, sedit annos duos, mense socto, dies triginta \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 BHL In\u233 \'e9dits S. 359; (172va\endash 173ra)\plain \f1\i\lang1033\fs22  De sanctis Sergio et Bacho \plain \f2\fs22 (sp\u228 \'e4tere Hand:\plain \f1\i\lang1033\fs22  Marcelli et Apulei\plain \f2\fs22 ).\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[110].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Sergius et Bachus honoribus sublimati in palacio Maximiani clari habebantur \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (7. Okt.), PL 123, Sp. 375 f.; (173ra\endash 174rb)\plain \f1\i\lang1033\fs22  De sancto Dyonisio\plain \f2\fs22 . LA 149; (174rb\endash vb)\plain \f1\i\lang1033\fs22  De sanctis Gereone et Victore. {\field{\*\fldinst HYPERLINK "hida://5650[111].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Apud Coloniam Gereonis et Victoris et sociorum eius. Hii milites egregii ex numero legionis Thebee \u8230 \'85}}\plain \f2\fs22 ; (174vb\endash 175vb)\plain \f1\i\lang1033\fs22  De eisdem. {\field{\*\fldinst HYPERLINK "hida://5650[112].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Gereon, Victor, Cassius et Florentius ex legione Thebea, cui dux inclitus Mauricius preerat, hoc ordine passi sunt \u8230 \'85}}\plain \f2\fs22 ; (175vb\endash 176ra)\plain \f1\i\lang1033\fs22  De sancto Kalixto\plain \f2\fs22 . LA 150; (176ra\endash vb)\plain \f1\i\lang1033\fs22  De sanctis Mauris. {\field{\*\fldinst HYPERLINK "hida://5650[113].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 De Mauritania, que est pars Affrice finitimisque regionibus, milites ab imperatore propter frequentes Gallorum tumultus evocati in Galliam navigio venerunt \u8230 \'85}}\plain \f2\fs22 ; (176vb\endash 177ra)\plain \f1\i\lang1033\fs22  De sancto Eliphio. {\field{\*\fldinst HYPERLINK "hida://5650[114].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Odibilis deo apostata Iulianus repletus est ira magna \u8230 \'85}}\plain \f2\fs22 ; (177ra\endash rb)\plain \f1\i\lang1033\fs22  De sancto Gallo. {\field{\*\fldinst HYPERLINK "hida://5650[115].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Sanctus Gallus, cuius hodie nataliciam celebramus, Scotorum nacione oriundus, sub regulari disciplina a beato Columbano abbate a puericia nutritus est.Hic ad australem latus est partem \u8230 \'85}}\plain \f2\fs22 ; (177rb\endash vb) \plain \f1\i\lang1033\fs22 De sancto Luca. {\field{\*\fldinst HYPERLINK "hida://5650[116].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Lucas evangelista, qui consurgens seu elevans interpretatur, natione Syrus de Antiochia, arte medicus fuit, domino adhesit, unus de septuaginta duobus discipulis fuit. Hic Paulum sequens est neque uxorem umquam habuit, neque filios, virginitatem servavit \u8230 \'85}}\plain \f2\fs22 ; (177vb\endash 179rb)\plain \f1\i\lang1033\fs22  De undecim milibus virginum. {\field{\*\fldinst HYPERLINK "hida://5650[117].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Apud Coloniam undecim milium virginum. Fuit in Britanie partibus rex quidam colens Chistum, cui optanti, ut haberet filium, regni succesorem, dedit dominus prolem femineam \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 BHL (Novum Suppl.) Nr. 8430a (?); (179rb\endash vb)\plain \f1\i\lang1033\fs22  De sancto Severo. {\field{\*\fldinst HYPERLINK "hida://5650[118].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Severus, Ravenne civitatis episcopus, ante susceptum episcopatum in laycali habitu constitutus pauperem vitam gerebat \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 BHL In\u233 \'e9dits S. 373 (?); (179vb\endash 180va)\plain \f1\i\lang1033\fs22  De sancto Severino. {\field{\*\fldinst HYPERLINK "hida://5650[119].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Apud Coloniam Agrippinam beatus Severinus episcopus condempnato Effrata Arriano a beato Maximino, Treverorum archiepiscopo, in antistitem est consecratus \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 k\u252 \'fcrzere Fassung \u252 \'fcberliefert in Ms. C 6, 326rb\endash va; (180va\endash 181va)\plain \f1\i\lang1033\fs22  De sancto Evergislo. {\field{\*\fldinst HYPERLINK "hida://5650[120].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Fuit Evergislus Tungrorum civitate oriundus, que quidam civitas tunc temporis Evergisli Gallicarum urbium maxima \u8230 \'85}}\plain \f2\fs22 ; (181va\endash 182ra)\plain \f1\i\lang1033\fs22  De sanctis Crispino et Crispiniano\plain \f2\fs22 . BHL (Novum Suppl.) Nr. 1992 (Schluss abweichend); (182ra\endash 183va)\plain \f1\i\lang1033\fs22  De sanctis Symone et Juda. {\field{\*\fldinst HYPERLINK "hida://5650[121].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Symon, qui obediens interpretatur, Cananeus a Matheo et Marco et Luca vero Zelotes, quod idem sonat cognominatur \u8230 \'85}}\plain \f2\fs22 ; (183va\endash 184rb)\plain \f1\i\lang1033\fs22  De sancto Narcisso. {\field{\*\fldinst HYPERLINK "hida://5650[122].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Nativitas sancti Narcissi, Iherosolimorum episcopi, viri sanctitate et paciencia et fide laudabilis \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (29. Okt.), PL 123, Sp. 385 f.; (184rb\endash 185vb)\plain \f1\i\lang1033\fs22  De sancto Quintino\plain \f2\fs22 . BHL Nr. 6999 (ohne Prolog); (185vb\endash 187rb) SERMO DE OMNIBUS SANCTIS.\plain \f1\i\lang1033\fs22  De omnibus sanctis. {\field{\*\fldinst HYPERLINK "hida://5650[123].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ecce omnes solempnitates tocius anni in hodierna die concluduntur, ideoque quod singulis sanctorum festivitatibus negleximus, in hac die emendare studeamus \u8230 \'85}}\plain \f2\fs22 ; (187rb\endash vb)\plain \f1\i\lang1033\fs22  De sancto Cesareo\plain \f2\fs22 . BHL Nr. 1515; (187vb\endash 188va)\plain \f1\i\lang1033\fs22  De sancto Eustachio. {\field{\*\fldinst HYPERLINK "hida://5650[124].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 In diebus Traiani imperatoris erat quidam dux nomine Placidus, secundum carnem nobilis, dives et honestus\u8230 \'85}}\plain \f2\fs22 ; (188va\endash 189rb)\plain \f1\i\lang1033\fs22  De sancto Huperto. {\field{\*\fldinst HYPERLINK "hida://5650[125].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Hupertus, beato Lamberto in episcopatu Traiectensis ecclesie succedens, omni virtutum operi fideliter institit \u8230 \'85}}\plain \f2\fs22 ; (189rb\endash 190rb) \plain \f1\i\lang1033\fs22 De sancto Leonardo. \plain \f2\fs22 LA 151; (190rb\endash 191rb)\plain \f1\i\lang1033\fs22  De sancto Willibrordo\plain \f2\fs22 . BHL Nr. 8935 (Schluss abweichend); (191rb\endash vb)\plain \f1\i\lang1033\fs22  De quatuor coronatis. {\field{\*\fldinst HYPERLINK "hida://5650[126].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Claudius, Nycostratus, Symphorianus, Simplicius }}{\field{\*\fldinst HYPERLINK "hida://5650[126].5666l/?u"}{\fldrslt \plain \f2\fs22\chcbpat17 (191va) }}{\field{\*\fldinst HYPERLINK "hida://5650[126].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 et Castorus cum essent opifices optimi et marmorum cesores probatissimi, imperatori dyocleciano valde sunt accepti ...}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (8. Nov.), PL 123, Sp. 391 f. (191vb\endash 193ra)\plain \f1\i\lang1033\fs22  De sancto Theodero. {\field{\*\fldinst HYPERLINK "hida://5650[127].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Tempore Maximiani et Maximi imperatorum tentus est beatus Theodorus \u8230 \'85}}\plain \f2\fs22 ; (193ra\endash 194rb)\plain \f1\i\lang1033\fs22  De sancto Martino\plain \f2\fs22 . {\field{\*\fldinst HYPERLINK "hida://5650[128].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Nativitas sancti Martini pape. Qui ob fidem catholicam ab imperatore Constantino heretico \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (10. Nov.), PL 123, Sp. 393; (193ra\endash 194rb)\plain \f1\i\lang1033\fs22  De sancto Martino episcopo\plain \f2\fs22 .\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[129].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Igitur Martinus Sabarie Pannoniorum oriundus fuit opido, parentibus nobilibus, sed tamen gentilibus intra Ytaliam Papie nutritus \u8230 \'85}}\plain \f2\fs22 ; (194rb\endash vb)\plain \f1\i\lang1033\fs22  De sancto Menna. {\field{\*\fldinst HYPERLINK "hida://5650[130].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 In Sitia }}{\field{\*\fldinst HYPERLINK "hida://5650[130].5666l/?u"}{\fldrslt \plain \f2\fs22\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[130].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 , metropoli Frigie Salutarie, passio sancti Menne martyris \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f2\fs22 Ado, Mart. (11. Nov.), PL 123, Sp. 393 f.; (194vb\endash 195ra)\plain \f1\i\lang1033\fs22  De sancto Cuniberto. In Crallo, provincie Mosselensis, clarus indigena \u8230 \'85 \plain \f2\fs22 vgl. BHL (Novum Suppl.) Nr. 2018a; Text \u252 \'fcberliefert auch in Ms. C 6, 326va; (195ra\endash vb) S. Britius (13. Nov.; \u220 \'dcberschrift durch Abrieb unleserlich geworden). BHL Nr. 1452 (unvollst\u228 \'e4ndig). Das Kapitelverzeichnis (1rv) nennt zw\u246 \'f6lf weitere Legenden, die in der Hs. fehlen.}

