\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs22 Kurz, Augustinus, 5,2, S. 145 \u183 \'b7 van de Pasch, Bibliotheca, S. 14 \u183 \'b7 Lambert Bd. 4B, S. 65 und 180 \u183 \'b7 Kr\u228 \'e4mer S. 167 \u183 \'b7 Handschriftencensus Rheinland Nr. 672.}

