\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 102ra\endash 123vb [{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 VERBA SENIORUM}}\plain \f1\fs22 ] (= Vitaspatrum, lib. 3, 5, 6).\plain \f2\i\lang1033\fs22  Vere mundum quis dubitet meritis stare sanctorum \u8230 \'85 \plain \f1\fs22 \endash  (102rb)\plain \f2\i\lang1033\fs22  \u8230 \'85 ad eternam salutem\plain \f1\fs22 . (102rb)\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Quidam sanctorum seniorum patrum interrogantibus se monachis de causa abstinencie \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 \endash \plain \f2\i\lang1033\fs22  \u8230 \'85 interiori homini nostro sanitas inde crescit\plain \f1\fs22 . \endash  Druck: PL 73, Sp. 739\endash 810 und 855\endash 988 (abweichende und umfangreichere Fassung). BHL Nr. 6525. Fassung und Reihenfolge der Abschnitte entsprechen der Editio prima. Text \u252 \'fcberliefert auch in Ms. B 54, 27va.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset1 Times New Roman;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

