\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs22 Bl. 173\endash 193: {\field{\*\fldinst HYPERLINK "hida://5130[0]/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 Nordwestdeutschland}}\plain \f2\lang1033\fs22 , {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 um 1435/40}}\plain \f2\lang1033\fs22  \u183 \'b7 Wz.: Traube Siebpaar Gruppe PiccFr I 809\endash 821 (1437/40), vgl. Teil I dieser Hs. \u183 \'b7 Lagen: V182 + (VI\endash 1)193 \u183 \'b7 ausgeschnittene Bll. ohne Textverlust moderne Foliierung in Bleistift (\plain \f2\i\lang1033\fs22 173\plain \f2\lang1033\fs22 \endash \plain \f2\i\lang1033\fs22 193\plain \f2\lang1033\fs22 ) \u183 \'b7 Schriftraum 14\endash 15,5 x 22\endash 23,5 \u183 \'b7 35\endash 47 Zeilen \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 gotische Kursive}}\plain \f2\lang1033\fs22  \u183 \'b7 eine Hand (auch Teil I dieser Hs., Hand B) \u183 \'b7 rubriziert; 3\endash 5-zeilige rote {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 Lombarden}}\plain \f2\lang1033\fs22 .}

