\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs22 Purpurroter Samtbezug \u252 \'fcber Pappe; wahrscheinlich Arbeit der Werkstatt der {\field{\*\fldinst HYPERLINK "hida://bezsoz[1].4600/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 Zisterzienserabtei Altenberg}}\plain \f2\lang1033\fs22 , {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 17. Jh., 1. H\u228 \'e4lfte}}\plain \f2\lang1033\fs22  (vgl. Teil II der Hs.) \u183 \'b7 auf dem Vorder- und R\u252 \'fcckdeckel Spuren von Beschl\u228 \'e4gen; Schlie\u223 \'dfb\u228 \'e4nder aus gr\u252 \'fcnem Stoff (unvollst\u228 \'e4ndig) \u183 \'b7 auf dem R\u252 \'fccken Reste eines Titelschildes (D\u252 \'fcsseldorf, nach 1803) \u183 \'b7 Schnitt vergoldet.}

