\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 43v\endash 52v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 DE BENEDICTIONE ABBATIS SECUNDUM ORDINARIUM ECCLESIAE COLONIENSIS}}\plain \f1\fs22 . >\plain \f2\i\lang1033\fs22  Item ordo ad benedicendum abbatem secundum ordinarium Coloniensis ecclesie\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Die dominica, hora terciarum, ponatur in medio chori circa altare mensa supposito mensali mundo et desuper ponantur due magne semelle et due magne flasce cum vino \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 (46r) >\plain \f2\i\lang1033\fs22 Oremus\plain \f1\fs22 .< PRG XXVI, Nr. 5; Rituale cisterciense S. 514; (46v) >\plain \f2\i\lang1033\fs22 Oremus\plain \f1\fs22 .< PRG XXVI, Nr. 6; Deshusses Nr. 4239; Rituale cisterciense S. 514; (48r) >\plain \f2\i\lang1033\fs22 Oremus\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Exaudi, domine, preces nostras, quas in conspectu tue maiestatis fundimus super hunc famulum tuum \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 Rituale cisterciense S. 517 f.; (49v) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Rex omnipotens et piissime, te deprecamur, domine, hunc famulum tuum propicius intuere \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 Rituale cisterciense S. 520; >\plain \f2\i\lang1033\fs22 Benedictio cirothecarum\plain \f1\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Immensam clemenciam tuam, omnipotens et piissime dues, humiliter imploramus \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 >\plain \f2\i\lang1033\fs22 Oremus\plain \f1\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Circumda, domine, manus huius famuli tui mundicia novi }}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 (50r)}}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17  hominis \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 Rituale cisterciense S. 524 f.; >\plain \f2\i\lang1033\fs22 Benedictio baculi\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Omnipotens et misericors deus, qui ineffabili bonitate votis supplicancium assistis \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 >\plain \f2\i\lang1033\fs22 Oremus\plain \f1\fs22 .< PRG XXVI, Nr. 14, 15a; ebd. XXXII, Nr. 14; Rituale cisterciense S. 516; >\plain \f2\i\lang1033\fs22 Benedictio annulorum\plain \f1\fs22 .< Deshusses Nr. 4089; Rituale cisterciense S. 519 f.; (51r) PRG XXVI, Nr. 15; Rituale cisterciense S. 516 f.; (52v) >\plain \f2\i\lang1033\fs22 Oremus\plain \f1\fs22 .< Deshusses Nr. 31; Rituale cisterciense S. 527. >\plain \f2\i\lang1033\fs22 Istis completis cum summa reverencia exeant chorum et vestimenta sacra in armario deponant\plain \f1\fs22 .<}

