\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 52v\endash 53r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 FORMAE IURAMENTI CONSILIARIORUM, OFFICIALIUM, CONVERSORUM ET FRATRUM LAICORUM}}\plain \f1\fs22 . >\plain \f2\i\lang1033\fs22 Item iuramentum consiliariorum manu pectore imposita\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Ego frater N iuro domino meo abbati fidele prestare consilium per ipsum requisitus \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 >\plain \f2\i\lang1033\fs22 Juramentum officialium dum instituuntur ad aliquod officium extensis prioribus tribus digitis aut manu pectore imposita\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Ego frater N inofficio iam mi}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 - (53r) -}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 hi commisso iuxta Benedictine}}\plain \f2\i\lang1033\fs22  et ordinis mei cisterciensis statuta me fidelem diligentemque in omnibus exhibet. Sic me deus adiuvet et omnes sancti eius\plain \f1\fs22 . >\plain \f2\i\lang1033\fs22 Juramentum in vulgari lingua pro conversis et laicis fratribus\plain \f1\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Ich broider N geloeuen, dat ich dit ampt, dat myr huyde van myns cloisters wegen beuoilen wirt,}}\plain \f2\i\lang1033\fs22  wil truwelichen in vlyslichen regeren ind bewaren ind tzo gesynnen myner oeuersten weder oeuergeuen, so myr got help ind alle syne hilligen\plain \f1\fs22 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset1 Times New Roman;}{\f2\fnil\fcharset0 Times New Roman;}{\f3\fnil\fcharset0 Calibri;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

