\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 54rv {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 PROFESSIO CONVERSORUM}}\plain \f1\fs22 . >\plain \f2\i\lang1033\fs22 Item sequitur professio conversorum secundum diffiniciones dis. xiiii, capitulo primo\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Post annum veniat conversus novicius in capitulum monachorum petens veniam prostratus \u8230 \'85}}\plain \f2\i\lang1033\fs22  \endash  \u8230 \'85 \plain \f1\fs22 >\plain \f2\i\lang1033\fs22 Et osculatus ab abbate exeat et discedat\plain \f1\fs22 .}

