\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 54v\endash 55r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 PROFESSIO DONATORUM}}\plain \f1\fs22 , ripuarisch. >\plain \f2\i\lang1033\fs22 Item professio donatorum et fiat coram aliquo altare hoc modo presentibus aliquibus testibus et notario\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Ich N van N offeren mych myt myme vryen willen tzoe ygenschaf der hilliger dryueldicheit ind Marien, der moder gotz, dem hilligen orden van Cistercien ind dem cloister tzom N ind gelouen uch, her abt, in vren nakomelingen abten tzom N gehoirsam tzo syn yn allen saichen\u8230 \'85}}\plain \f2\i\lang1033\fs22  \endash  \u8230 \'85 Ind bidden uch her notarium her vp eyn wairaftich instrument tzo maichen ind dem vurscreuen cloister tzo geuen\plain \f1\fs22 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset1 Times New Roman;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

