\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 241ra\endash 245rb {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 GREGORIUS}}\plain \f1\fs22 . >\plain \f2\i\lang1033\fs22 Van sante Gregorius vp dem mer\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Id was eyn edel man ende was eyn greue to Aquitanien, die in vil doichden lange tijt leuede \u8230 \'85}}\plain \f2\i\lang1033\fs22  \endash  \u8230 \'85 Dat en leiffde wyff noch man herna, dat hie in dat ewige leuen quam. Des helpe ons alle samen die ewige vader. Amen\plain \f1\fs22 . \endash  V. Mertens,\plain \f2\charscalex99\expndtw45\lang1033\fs22  \plain \f1\fs22 Gregorius\plain \f2\expndtw30\lang1033\fs22  \plain \f1\fs22 Eremita.\plain \f2\expndtw30\lang1033\fs22  \plain \f1\fs22 Eine\plain \f2\expndtw30\lang1033\fs22  \plain \f1\fs22 Lebensform\plain \f2\expndtw30\lang1033\fs22  \plain \f1\fs22 des\plain \f2\expndtw30\lang1033\fs22  \plain \f1\fs22 Adels\plain \f2\expndtw30\lang1033\fs22  \plain \f1\fs22 bei\plain \f2\expndtw30\lang1033\fs22  \plain \f1\fs22 Hartmann\plain \f2\expndtw30\lang1033\fs22  \plain \f1\fs22 von\plain \f2\expndtw30\lang1033\fs22  \plain \f1\fs22 Aue\plain \f2\expndtw30\lang1033\fs22  \plain \f1\fs22 in\plain \f2\charscalex99\expndtw60\lang1033\fs22  \plain \f1\fs22 ihrer\plain \f2\expndtw45\lang1033\fs22  \plain \f1\fs22 Problematik\plain \f2\expndtw45\lang1033\fs22  \plain \f1\fs22 und\plain \f2\expndtw45\lang1033\fs22  \plain \f1\fs22 ihrer\plain \f2\expndtw45\lang1033\fs22  \plain \f1\fs22 Wandlung\plain \f2\expndtw45\lang1033\fs22  \plain \f1\fs22 in\plain \f2\expndtw45\lang1033\fs22  \plain \f1\fs22 der\plain \f2\expndtw45\lang1033\fs22  \plain \f1\fs22 Rezeption,\plain \f2\expndtw45\lang1033\fs22  \plain \f1\fs22 M\u252 \'fcnchen\plain \f2\expndtw45\lang1033\fs22  \plain \f1\fs22 1978 (MTU, 67), S.\plain \f2\expndtw-30\lang1033\fs22  \p