\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 Bl. 30\endash 91: {\field{\*\fldinst HYPERLINK "hida://bezsoz[0].4600/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 Werden, Benediktinerabtei}}\plain \f1\fs22 , {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 um 1520}}\plain \f1\fs22  \u183 \'b7 Wz.: Sonne, nicht identifiziert, vgl. Piccard-Online Nr. 41270 (1519), 41273 (1514), 41283 (1523), auch in Ms. C 66 und Ms. C 71: jeweils Werden, Benediktinerabtei, um 1520; Buchstabe P ~\plain \f2\expndtw-15\lang1033\fs22  \plain \f1\fs22 PiccP VII 490 (1518); ein Wz. nicht identifizierbar; Lilie\plain \f2\charscalex99\expndtw105\lang1033\fs22  \plain \f1\fs22 Gruppe\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 PiccLi\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 III\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 1804\endash 1808\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 (1518,\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 1519),\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 auch\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 in\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 Teil\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 IV\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 dieser\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 Hs. \u183 \'b7\plain \f2\expndtw45\lang1033\fs22  \plain \f1\fs22 Lagen:\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 IV37\plain \f2\expndtw30\lang1033\fs22  \plain \f1\fs22 +\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 (VII\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 +\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 2\plain \f2\charscalex99\expndtw60\lang1033\fs22  \plain \f1\fs22 Schaltbll.)53\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 + (VI\endash 1)64\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 + (VII + 2 Schaltbll.)80\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 + (VI\endash 1)91\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 \u183 \'b7\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 Textverlust zwischen Bl. 63 und 64\plain \f2\expndtw15\lang1033\fs22  \plain \f1\fs22 \u183 \'b7\plain \f2\charscalex75\expndtw90\lang1033\fs22  \plain \f1\fs22 Lagenz\u228 \'e4hlung: \plain \f2\i\lang1033\fs22 d\plain \f1\fs22 , \plain \f2\i\lang1033\fs22 e\plain \f1\fs22 , \plain \f2\i\lang1033\fs22 f\plain \f1\fs22 , \plain \f2\i\lang1033\fs22 g\plain \f2\i\expndtw45\lang1033\fs22  \plain \f1\fs22 \u183 \'b7\plain \f2\expndtw45\lang1033\fs22  \plain \f1\fs22 moderne Foliierung in Bleistift (\plain \f2\i\lang1033\fs22 30\plain \f1\fs22 \endash \plain \f2\i\lang1033\fs22 91\plain \f1\fs22 ); Schaltbll. mitgez\u228 \'e4hlt\plain \f2\expndtw45\lang1033\fs22  \plain \f1\fs22 \u183 \'b7\plain \f2\expndtw45\lang1033\fs22  \plain \f1\fs22 Schriftraum bis Bl. 37r: 10,5 x 7,5; 10,5\endash 12,5 x 7,5\endash 8\plain \f2\expndtw30\lang1033\fs22  \plain \f1\fs22 \u183 \'b7 \plain \f2\expndtw30\lang1033\fs22  \plain \f1\fs22 bis Bl. 37r: 21 Zeilen; 16\endash 32 Zeilen \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 Semihybrida}}\plain \f1\fs22  und {\field{\*\fldinst HYPERLINK "hida://5704[1]/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 Hybrida}}\plain \f1\fs22  (Hand A); {\field{\*\fldinst HYPERLINK "hida://5704[2]/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 sp\u228 \'e4tgotische Kursive}}\plain \f1\fs22  (Hand B) \u183 \'b7 zwei H\u228 \'e4nde (A: 30r\endash 37v; B = {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 Johannes von Groningen}}\plain \f1\fs22 : 38r\endash 91r und Notiz auf Bl. 37v) \u183 \'b7 rubriziert.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset1 Times New Roman;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

