\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 45v\endash 54v [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 HENRICUS DE BITTERFELD}}\plain \f1\fs22 ]: {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 DE HORIS CANONICIS}}\plain \f1\fs22 .\plain \f2\i\lang1033\fs22  >De septem horis canonicis.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Sepcies in die \u8230 \'85 }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 [Ps 118,164]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 . Quamvis deus semper et omni tempore a nobis sit laudandus \u8230 \'85}}\plain \f2\i\lang1033\fs22  \endash  \u8230 \'85 sic qui devote septem horas cottidie deo persolverit, vitam eternam habebit. Quam nobis concedat etc\plain \f1\fs22 . \endash  Drucke: GW 12194\endash 12198. Kaeppeli Nr. 1716. DLLMA Bd. 2, Sp. 652\endash 655, hier Sp. 653. Text \u252 \'fcberliefert auch in Ms. B 171, 147r\endash 157r, vgl. Kat. D\u252 \'fcsseldorf, Bd. 2, S. 252 f. Anschlie\u223 \'dfend Verse: >\plain \f2\i\lang1033\fs22 Nota. Psalmodiam sic psallamus, verba recte perlegamus \u8230 \'85 \endash  \u8230 \'85 sit ut deo placeamus eterna promerendo\plain \f1\fs22 .<}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset1 Times New Roman;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

