\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 137rv\plain \f2\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 ORATIONES}}\plain \f1\fs22 . ||\plain \f2\i\lang1033\fs22  intervenire et intremenda exitus \plain \f1\fs22 [\u8230 \'85]\plain \f2\i\lang1033\fs22  tempore hora cum omni celestis exercitus \u8230 \'85 \endash  \u8230 \'85 et celestium gaudiorum confortibus aggregari eternaliter. Amen. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Beatissime Iohannes Baptista, precursor et martyr Christi \u8230 \'85}}\plain \f2\i\lang1033\fs22  \endash  \u8230 \'85 militare sibi. Amen. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Sanctissimi apostoli domini nostri Ihesu Christi, beatissime Petre, Paule, Andrea, Jacobe \u8230 \'85}}\plain \f2\i\lang1033\fs22  \endash  \u8230 \'85 in extremo agmine \plain \f1\fs22 (?)\plain \f2\i\lang1033\fs22  vestro. Amen. Te dominum supplico omnipotenten subnixis precibus \u8230 \'85 \endash  \u8230 \'85 \plain \f1\fs22 (137v) et\plain \f2\i\lang1033\fs22  oblectamenta istius mun\plain \f1\fs22 <\plain \f2\i\lang1033\fs22 eris \plain \f1\fs22 ?>\plain \f2\i\lang1033\fs22  superare. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Obsecro vos, confessores Christi atque doctores, Cypriane, Basilii, Gregori, Athanasi \u8230 \'85}}\plain \f2\i\lang1033\fs22  \endash  \u8230 \'85 consortio gratulari. Amen. \plain \f1\fs22 Am linken Rand sp\u228 \'e4terer Nachtrag:\plain \f2\i\lang1033\fs22  Bernarde, Roberte. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Intercedite pro me nimiis obnoxium peccatis, omne sancte virgines martyresque Christi \u8230 \'85}}\plain \f2\i\lang1033\fs22  \endash  \u8230 \'85 at esse consortem. Qui vivit\plain \f1\fs22 . Textverluste durch Blattbesch\u228 \'e4digung.}

