\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 143v\endash 145v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 SYMBOLUM ATHANASIANUM}}\plain \f1\fs22 . >\plain \f2\i\lang1033\fs22 Fides catholica\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Quicumque vult salvus esse \u8230 \'85}}\plain \f2\i\lang1033\fs22  \endash  \u8230 \'85 salvum esse non poterit. \plain \f1\fs22 CPL Nr. 167; CPPM Bd. 2, Nr. 38, 699. (145v) SYMBOLUM APOSTOLORUM. >\plain \f2\i\lang1033\fs22 Fides apostolica\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Credo in deum patrem omnipotentem \u8230 \'85}}\plain \f2\i\lang1033\fs22  \endash  \u8230 \'85 carnis resurrectionem et vitam eternam\plain \f1\fs22 .}

