\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 151v ORATIONES, unvollst\u228 \'e4ndig (zusammengeh\u246 \'f6rig mit Bl. 1r). >\plain \f2\i\lang1033\fs22 De adventu domini\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Ave spes nostra, dei genitrix Maria, virgo intacta \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 zum Anfang des Gebetes vgl. Meersseman, Hymnos, Bd. 1, S. 181, Nr. 32.3 (mit Abweichungen);\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 O caritas patris, domine Ihesu Christe, veni et noli tardare \u8230 \'85}}\plain \f1\fs22 ;\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Domine Ihesu Christe, miserere michi, famule tue, et fidelis tuis per gloriosam incarnationem tuam \u8230 \'85}}\plain \f1\fs22 ; >\plain \f2\i\lang1033\fs22 Collecta\plain \f1\fs22 .< CO Nr. 4631. >\plain \f2\i\lang1033\fs22 De nativitate domini\plain \f1\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Christe, fili dei vivi, splendor paterni luminis \u8230 \'85}}\plain \f2\i\lang1033\fs22  benedicimus \plain \f1\fs22 ||}

