\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 67r\endash 91r\plain \f2\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 ROSARIUM VITAE ET PASSIONIS IESU CHRISTI}}\plain \f1\fs22 . >\plain \f2\i\lang1033\fs22 Rosarium misticum anime fidelis quinquaginta articulis tocius vite passionisque domini nostri Jesu Christi ac totidem piis precaciunculis ceu vernis floribus secundum fidem sancti evangelii consitum. Ad vulnus dextri pedis oracio\plain \f1\fs22 .< (67v)\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Amabilissime atque dulcissime Iesu Christe, sit tibi laus, honor et gloria pro vulnere et dolore dextri pedis tui \u8230 \'85}}\plain \f2\i\lang1033\fs22  \endash  \u8230 \'85 ut tibi perfecte placere valeam hic et sine fine. Amen\plain \f1\fs22 . Anschlie\u223 \'dfend Versikel:\plain \f2\i\lang1033\fs22  Vulneratus est propter iniquitates nostras, attritus est propter scelera nostra \plain \f1\fs22 und (91r\endash 92v) ORATIONES AD VULNERA CHRISTI. >\plain \f2\i\lang1033\fs22 Oracio\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  Domine Jesu Christe, per sanctissima quinque vulnera, que in cruce pro nobis pertulisti \u8230 \'85\plain \f1\fs22 ; (91v) >\plain \f2\i\lang1033\fs22 Pro sequenti oracione tot dies \plain \f2\lang1033\fs22 (\plain \f1\fs22 sp\u228 \'e4terer Nachtrag:\plain \f2\i\lang1033\fs22  meritorum\plain \f1\fs22 ),\plain \f2\i\lang1033\fs22  quot Christus vulnera habuit\plain \f1\fs22 .< (92r)\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Precor te, amantissime domine Jesu Christe, per illam eximiam charitatem, qua humanum genus dilexisti}}\plain \f2\i\lang1033\fs22  \u8230 \'85 \plain \f1\fs22 Leroquais, Livres d\rquote heures 1, S. XXXI und 336; vgl. ebd. 2, S. 443 (Register: Precorte, piissime \u8230 \'85); Haimerl, Gebetbuchliteratur, S. 80, Anm. 457 und S. 124, Anm. 735; Wilmart, Auteurs spirituels, S. 377, Anm. 1, Nr. 12; Deschamps/Mulder, Inventaris, S. 90, G64.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset1 Times New Roman;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

