\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 106v\endash 109v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 MECHTHILD [VON HACKEBORN}}\plain \f1\fs22 :\plain \f2\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 LIBER SPECIALIS GRATIAE}}\plain \f1\fs22 ], pars 1, cap. 19 (Exzerpt). >\plain \f2\i\lang1033\fs22 Oraciones quinque de quinque gaudiis dominice resurrectionis, que quicumque devote legerit, maximam a domino consequitur graciam, prout revelatum fuit sacre virgini Mechtildi\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Laudo, adoro, magnifico, glorifico et benedico te, Iesu bone, in illo in- }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 (107r)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17  -effabili gaudio \u8230 \'85}}\plain \f2\i\lang1033\fs22  \endash  \u8230 \'85 unicum gaudium et omne bonum, nunc hic et in eternum. Amen\plain \f1\fs22 . \endash  Druck: Revelationes Gertrudianae et Mechtildianae, Bd. 2: S. Mechtildis virginis ordinis s. Benedicti Liber specialis gratiae. Opus editum Solesmensium O.S.B. monachorum cura et opera, Paris 1877, S. 65\endash 67.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset1 Times New Roman;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

