\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 110v\endash 115r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 ORATIONES DE PASSIONE DOMINI}}\plain \f1\fs22 . >\plain \f2\i\lang1033\fs22 Oratio ad dominum nostrum Iesum de quinque doloribus potissimis, quos in sua beatissima passione sustinuit\plain \f1\fs22 .< (111r) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 O amantissime Iesu, moneo te illius agonis, qui inter animam et corpus tuum fuit ex virtute amoris et timoris tue passionis \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 \endash \plain \f2\i\lang1033\fs22  \u8230 \'85 in sinu matris tue virginis Marie iacuisti. Amen\plain \f1\fs22 . Haimerl, Gebetbuchliteratur, S. 92, Anm. 551; (111v) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 O mitissime agne dei, Iesu Christe immaculate, moneo te illius horribilis casus \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 \endash \plain \f2\i\lang1033\fs22  \u8230 \'85 pie laudare et eternaliter tecum gaudere merear. Amen\plain \f1\fs22 . (112v)\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 O unice amator meus Iesu Christe, moneo te illius compassionis et tremoris \u8230 \'85}}\plain \f1\fs22 ; (113r) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 O refugium delectabile omnium desolatorum Iesu Christe, moneo te illius angustie \u8230 \'85}}\plain \f1\fs22 ; (114r) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 O dulcissime Iesu, moneo te illius doloris et anxietatis, in quam devenisti \u8230 \'85}}\plain \f1\fs22 ; (114v) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Domine Iesu Christe, memento, quod tu dixisti: Vivo ego et nolo mortem peccatoris \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 \endash \plain \f2\i\lang1033\fs22  \u8230 \'85 In crucis patibulo te eternaliter videre valeam. Amen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset1 Times New Roman;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

