\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 115r\endash 120v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 ORATIONES AD SANCTAM CRUCEM}}\plain \f1\fs22 . >\plain \f2\i\lang1033\fs22 Oracio seu commendacio ad sanctam crucem\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  Signum sancte crucis defendat me a malis preteritis, presentibus et futuris, interioribus et exterioribus \plain \f1\fs22 \u8230 \'85 Haimerl, Gebetbuchliteratur, S. 91, Anm. 539; (116v)\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Sanctifica, domine, familiam tuam signaculo sancte crucis \u8230 \'85}}\plain \f1\fs22 ;{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Adesto nobis, domine, deus noster, et quos sancte crucis letari fecisti \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 CO Nr. 158 (mit Abweichungen); {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Deus, qui in vexillo sancte crucis nobis dona contulisti \u8230 \'85}}\plain \f1\fs22 ; (117r) >\plain \f2\i\lang1033\fs22 Oracio bona de sancta cruce et potest dici in die sancto parasceves, quando crux adoratur aut in utroque festo sancte crucis vel etiam quotidie coram imagine crucifixi\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Salve crux sancta, salve crux gloriosa, salve crux vivifica, salve mundi decus \u8230 \'85}}\plain \f1\fs22 ; (119v) >\plain \f2\i\lang1033\fs22 Oracio\plain \f1\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Sanctifica me, domine, hoc signaculo sancte crucis, ut fiat michi obstaculum contra seva iacula inimicorum omnium \u8230 \'85}}\plain \f1\fs22 ; >\plain \f2\i\lang1033\fs22 Alia oracio\plain \f1\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Crucem tuam adoramus, domine, et sanctam resurrectionem tuam laudamus et glorificamus \u8230 \'85}}\plain \f1\fs22 ; (120r) >\plain \f2\i\lang1033\fs22 Alia\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Sancta crux Christi, per te redemptus sum, per te merear veniam indulgenciam percipere \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 \endash \plain \f2\i\lang1033\fs22  \u8230 \'85 in presenti vita et in futuro \plain \f1\fs22 (120v)\plain \f2\i\lang1033\fs22  iudicio. Per infinita secula seculorum. Amen\plain \f1\fs22 .}

