\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 138rv {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 SEPTEM GAUDIA TERRESTRIA BMV}}\plain \f1\fs22 . >\plain \f2\i\lang1033\fs22 Septem gaudia terrestria beate Marie virginis\plain \f1\fs22 .< RH Nr. 7017; Meersseman, Hymnos, Bd. 2, S. 39 und 206; Leroquais, Livres d\rquote heures 2, S. 409 (Register); Wilmart, Auteurs spirituels, S. 329, Anm. 1 und S. 335. Anschlie\u223 \'dfend Versikel:\plain \f2\i\lang1033\fs22  Ora pro nobis \plain \f1\fs22 und (139r) >\plain \f2\i\lang1033\fs22 Oracio\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Deus, qui sacratissimam virginem Mariam in conceptu et partu dilecti filii tui virginitate servata duplici gaudio letificasti \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 \endash \plain \f2\i\lang1033\fs22  \u8230 \'85 et precibus pervenire mereamur. Per eundem Christum\plain \f1\fs22 . Leroquais, Livres d\rquote heures 1, S. 54.}

