\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 143r\endash 150r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 SALUTATIO MEMBRORUM BMV}}\plain \f1\fs22 . >\plain \f2\i\lang1033\fs22 Officium devotissimum et beate virgini gratissimum, scilicet salutacio omnium membrorum ipsius gloriose virginis tocius pulchritudinis elegancia et dulcedinis excellencia fulgentium \plain \f1\fs22 (\u8230 \'85).< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Suscipe, dei genitrix, omnipotentis regis obsequium humilis, servi tui indignas laudes ex ore ipsius immundo}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 \u8230 \'85}}\plain \f1\fs22 ; anschlie\u223 \'dfend (149r) Versikel:\plain \f2\i\lang1033\fs22  Singula membra pia tua \plain \f1\fs22 (149v)\plain \f2\i\lang1033\fs22  sint benedicta, Maria \plain \f1\fs22 und Gebet :{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Deus, qui nobis per Moysen, famulum tuum, mandato mandasti parentes nostros venerari \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 \endash \plain \f2\i\lang1033\fs22  \u8230 \'85 matrem digne venerari mereatur in celis. Qui vivis et reg\plain \f1\fs22 (nas).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset1 Times New Roman;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

