\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 160r\endash 165v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 ORATIONES ANTE COMMUNIONEM}}\plain \f1\fs22 .\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Omnipotens et misericors deus, ecce accedo ad sacramentum corporis et sanguinis dulcissimi filii tui \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 Druck: Thomas de Aquino, Opera omnia, Bd. 32, Paris 1879, S. 821, Nr. 6; Klapper, Schriften, S. 233\endash 235 und 245 f. Leroquais, Livres d\rquote heures 1, S. 258; ebd. 2, S. 37, 39; Wilmart, Auteurs spirituels, S. 381, Anm. 2; Deschamps/Mulder, Inventaris, S. 87, G50. Zur Verfasserfrage vgl. Grabmann S. 370; VL2 Bd. 9, Sp. 813\endash 838, bes. Sp. 834; (160v) >\plain \f2\i\lang1033\fs22 Alia\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 O domine Iesu Christe, quam }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 (161r) }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 horrenda et quam gravia sunt, que ego, miserrimus peccator, commisi contra te deum et creatorem meum \u8230 \'85}}\plain \f1\fs22 ; (162r) >\plain \f2\i\lang1033\fs22 Alia\plain \f1\fs22 .<\plain \f2\i\expndtw30\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Ad te, fontem misericordie, accedo ego, miser peccator, ergo digneris me lavare immundum }}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f2\i\expndtw30\lang1033\fs22\chcbpat17 \u8230 \'85}}\plain \f2\i\expndtw30\lang1033\fs22  \plain \f1\fs22 Druck: Thomas de Aquino, Opera omnia, Bd. 32, Paris 1879, S. 819,  Nr.1. Deschamps/Mulder, Inventaris, S. 94, G80. ZurVerfasserfrage vgl. Grabmann, S. 371, Anm.188; VL2 Bd. 9, Sp. 813\endash 838, bes. Sp. 835; (163r)\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 O deus meus, quantum peccavi corde per cogitacionem, delectacionem et consensum \u8230 \'85}}\plain \f1\fs22 ; (163v) >\plain \f2\i\lang1033\fs22 Oracio\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Deus, qui de indignis dignos facis, de peccatoribus iustos, de immundis mundos, munda cor meum et corpus meum \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 Leroquais, Livres d\rquote heures 1, S. 156; Haimerl, Gebetbuchliteratur, S. 20, Anm. 102; Wilmart, Auteurs spirituels, S. 118, Anm. 51; (164r) >\plain \f2\i\lang1033\fs22 Oracio\plain \f1\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Creator omnium rerum deus, pater omnipotens, cuius principium inicium non recipit \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 Haimerl, Gebetbuchliteratur, S. 97, Anm. 574; (165r) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Precibus et meritis sanctissime genitricis tue virginis Marie et omnium sanctorum tuorum miserere mei, clementissime pater \u8230 \'85}}\plain \f2\i\lang1033\fs22  \endash  \u8230 \'85 et ad societatem supernorum civium pervenire merear. Amen.}

