\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 140v\endash 149v {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 ARS MORIENDI}}\plain \f1\lang1033\fs22 . {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Materia de arte moriendi continet vi particulas: Prima de laude mortis et sciencia bene moriendi extat}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 ita oracio pressa non audax\plain \f1\lang1033\fs22 . Darunter Gebet (Nachtrag):{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Domine Ihesu Christe,fac me encenia et innovationes in templo cordis mei}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 sed semper te per gratiam in me habitare sentiam. Amen\plain \f1\lang1033\fs22 .}

