\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 6r\endash 53v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 CHRISTI LEIDEN IN EINER VISION GESCHAUT}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Hier begint die werdighe passie ende lijden ons liefs heeren Jhesu Christi, also si eenen gheesteliken mensce verthoont is\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Het was een mensce tot eender tijt in sijn gebet ende begeerde hertelic dat bitter lijden ons liefs heeren Jhesu Christi in der herten te dragen}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 Here, ic ben die arme mensce, dien gi behouden moecht in uwer grondelooser barmherticheit. Amen.\plain \f1\lang1033\fs22  >\plain \f1\i\lang1033\fs22 Dit versikel\plain \f1\lang1033\fs22  (?)\plain \f1\i\lang1033\fs22  is geopenbaert\plain \f1\lang1033\fs22 .< \endash  Ausgabe nach dieser Hs.: J. Marrow, Christi Leiden in einer Vision geschaut in the Netherlands, in: Ons geestelijk erf 43, 1969, S. 337\endash 380; vgl. dazu Scriptorium 25, 1971, S. 161, Nr. 258. VL2 Bd. 1, Sp. 1218\endash 1221 (Hs. genannt Sp. 1219) und ebd. Bd. 11, Sp. 317; DLL MA Bd. 2, Sp. 599 f. (Hs. genannt Sp. 600); A. Prica, Zwischen Literaturwissenschaft und Theologie \endash  \u8222 \'84Christi Leiden in einer Vision geschaut\ldblquote , in: Neophilologus 90, 2006, S. 53\endash 75.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

