\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 105r\endash 109v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 MEDITATION IN DER FASTENZEIT}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Hoemen die dagen ende die vren eeren sal, die Jhesus inder woestinen was, elcken dach een corte meditacie\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Negenhondert vren ende lx vren was onse lieue here inder woestinen in groten inwendigen bangigen lyden}}\plain \f1\i\lang1033\fs22  \u8230 \'85 >Meditacie.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Den iersten dach denct op die grote eenicheit Jhesu}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 ende namaels hen te gebruken inder ewicheit. Amen\plain \f1\lang1033\fs22 .}

