\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 110r\endash 113r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 EXEMPEL}}\plain \f1\lang1033\fs22 . >{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Een scone leringe van paciencie}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 .< }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Een vind bescreuen, dat een doctor es gheweest, die grote begerte hadde om te weten, welck den cortsten weg es op dese werelt om ter ewigher salicheit te comen}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 ende dat men die sonden scouwe\plain \f1\lang1033\fs22 . Anschlie\u223 \'dfend Spruch: >\plain \f1\i\lang1033\fs22 Nota bene\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Dat eewig leuen off dat eewig steruen / Een van tween, dat es ons eruen}}\plain \f1\lang1033\fs22 . Es folgt ein Seneca zugeschriebenes Exzerpt. (113v) Zwei weitere Exempel.{\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Eyn heylich man hadde altoes bij hem een vre werck}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (114r)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Het was een heylich man spreken syn ghebeth hoerde een stumme seer derlijc clagen}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 ende hadden muegen ontgaen die ewige verdoemenisse\plain \f1\lang1033\fs22 . Anschlie\u223 \'dfend Verse: >{\field{\*\fldinst HYPERLINK "hida://5650[4].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Wie syn die liefste vrinden ons heeren, / Die hen van sonden tot duechden keren}}\plain \f1\i\lang1033\fs22 . / Wie syn die gene, die godt behagen, / die veel lijden ende luttel clagen\plain \f1\lang1033\fs22 .<}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 114v\endash 115v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 GEBET ZU JESUS}}\plain \f1\lang1033\fs22 .\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ic bid v, o lieue heer, duer die wonde we heyligen voerhoots, dat ghy myn v sinnen wilt bewaren van alle sonden}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  Dieser Text war fr\u252 \'fcher zugeklebt mit Bl. 115 (dieses Bl. liegt lose bei). (115v)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O lieue here, ic bid v duer die wonde we heyligen ghebenediden voerhoets, dat ghy myn v sinnen wilt bewaren van alle sonden ende van alle quaet}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 ende alder heylige. Amen\plain \f1\lang1033\fs22 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

