\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 125v\endash 126v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 MESSGEBET}}\plain \f1\lang1033\fs22 .\plain \f1\i\lang1033\fs22  Messgebet\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Dit ghebedt salmen lessen onder die heylige misse\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O alder suetste brudegum mynder sielen, die haer hebt vander ewigher doot verlost ende met v heylich bloet ende passie ghecocht, ic bid v oetmoedelijc duer die werdichcheit we alder heylicsten lichames}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash \u8230 \'85 ende te steruen nv ende inder vren mynder doot. Amen\plain \f1\lang1033\fs22 . \endash  127 leer.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 128r\endash 133r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 MEDITATION \u220 \'dcBER DIE SCHMERZEN JESU}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Dit syn xxx inwendige ween, die ons heere vonden cruce gheleden heeft, die alle syn wtwendich te boeuenghingen, soe ons lieue heer selue gheopenbaert heeft een heyligen deuote persone ende seyde\plain \f1\lang1033\fs22 :< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Die jerste wee was, dat ic sach, dat ic die sonde des menschelijken geslechte dagelicken doetelich vergelden ende beteren most }}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 ende pyn, die ic leet inder verscheydinge mynder edelder sielen van mynen heyligen lichaem. Amen\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 133r\endash 134v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 EUCHARISTIEGEBET}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Een scoen ghebet tot den heyligen sacramente\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Weest ghegruet, o hoegeheyli}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 <}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 ge}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 > }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 drywuldicheit, weest ghegruet heer Jhesu Christe, ic aenbede dyn verborgen waerst, die hier bedeckt staet onder die ghedaente des broets ende }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (134v) }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 ende des wyns}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 maer v nich eewust moet loenen ende dancken sonder inde. Amen\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Pater noster\plain \f1\lang1033\fs22 .<}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

