\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 168r\endash 170v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 ORATIONES DIVERSAE}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Devota contemplacio ante communionem\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O domine Jesu Christe, fili dei vivi, concede, ut hec sacramenta celestia michi efficiantur salus et vita}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (169r) >\plain \f1\i\lang1033\fs22 Alia devota contemplacio ante communionem\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O vera, unica hostia mente laudando }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 , non exteriori censenda visu, sed interiori amplectenda visu vel affectu}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (169v) >\plain \f1\i\lang1033\fs22 Alia devota oracio\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Precor te, domine Jhesu Christe, propter illam caritatem, qua tu, rex celestis, pendebas in cruce}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (170v) >\plain \f1\i\lang1033\fs22 Oracio ad proprium angelum\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Rogo te, sancte angele dei, cui ego ad custodiendum comissa sum}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 Et auxilio ad vitam eternam perduci merear. Amen\plain \f1\lang1033\fs22 .}

