\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 361va\endash 375vb\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 BIRGITTA SUECICA}}\plain \f1\lang1033\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 SERMO ANGELICUS DE EXCELLENTIA VIRGINIS MARIAE.}}\plain \f1\lang1033\fs22  (361va \endash 362ra) Prolog. >\plain \f1\i\lang1033\fs22 Incipit prologus in sermone angelico de excellencia virginis\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Cum beata Brigida, principissa Nericie de regno Suecie, per plures annos habitaret in Roma in domo cardinalatus \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 qui vivit et regnat perhenniter cum eadem in secula seculorum. Amen\plain \f1\lang1033\fs22 . (362rb) Textanfang:\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Verbum, de quo evangelista Johannes in evangelio suo facit mencionem \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 cum omni devocione et caritate ipsum accipiendo, quod virginis nostre Marie dignissimis precibus idem Ihesus Christus, suus filius, vobis prestare dignetur, qui cum patre et spiritu sancto vivit et regnat deus per omnia secula seculorum. Amen\plain \f1\lang1033\fs22 . \endash  Ed.: S. Eklund (Hg.), Opera minora, Bd. 2, Stockholm 1972 (Samlingar, 8,2), Hs. genannt S. 11. CALMA Bd. 2,4, S. 411, Nr. 3.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

