\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs22 2r\endash 9v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 SEPTEM PSALMI PAENITENTIALES DE BMV CUM LETANIA}}\plain \f2\lang1033\fs22 . >\plain \f2\i\lang1033\fs22 Incipiunt septem psalmi de sancta Maria domina nostra\plain \f2\lang1033\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Domina, ne in furore dei sinas me corripi}}\plain \f2\i\lang1033\fs22  \u8230 \'85\plain \f2\lang1033\fs22  Sieben Bu\u223 \'dfpsalmen (Ps 6, 31, 37, 50, 101, 129 und 142), auf Maria umgedichtet, mit Antiphonen. Anschlie\u223 \'dfend (6v) Notlitanei:\plain \f2\i\lang1033\fs22  \u8230 \'85\plain \f2\lang1033\fs22  Druck: Meersseman, Hymnos, Bd. 2, S. 230 f. (mit Abweichungen). Vgl. Deschamps/Mulder, Inventaris, S. 82, G25 und G26\plain \f1\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset1 Times New Roman;}{\f2\fnil\fcharset0 Times New Roman;}{\f3\fnil\fcharset0 Calibri;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;\red255\green204\blue153;}

