\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs22 34v\endash 39v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 MARIENGEBETE MIT 12 AVEMARIA}}\plain \f2\lang1033\fs22 . >\plain \f2\i\lang1033\fs22 Dyt synt xii\plain \f2\lang1033\fs22  [!]\plain \f2\i\lang1033\fs22  gebetgen mit xii Ave Marie\plain \f2\lang1033\fs22  [!]\plain \f2\i\lang1033\fs22  syr nutz\plain \f2\lang1033\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Ich vermanen dich, werdiche moder vns here Jhesu Christi, dynre groser vnsprechlicher leifden, de du hattest tzo dem almechtichen gode ind he tzo dir, do }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 (35r) }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 he dich erwelt ober alle creaturen der engel ind der minschen}}\plain \f2\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 dyns leuen kyntz willen vnde meynre selen heil. Amen.\plain \f2\lang1033\fs22  Eine Reihe von insgesamt elf Gebeten mit jeweils zw\u246 \'f6lf Avemaria.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

