\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 39v\endash 41r {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 GEBET ZU CHRISTUS MIT 15 AVEMARIA}}\plain \f1\lang1033\fs22 .\plain \f1\i\lang1033\fs22  Der engel offenbayrde eynre devoter personen xv Ave Maria. So wilge minsche sy andichlichen lese vur eynniche sache, da de ere gotz\plain \f1\lang1033\fs22  (40r)\plain \f1\i\lang1033\fs22  in gesoicht ind begert worde, der sal uwerhoirt werden. Nu sprich v Ave Maria. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O leue here, dese v Ave Maria offeren ich dir zo dyn ewechen loue ind zo dinre ewiger eren}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 Erneuwe mich in deser sachen zo dym loue ind dynre eren. Amen\plain \f1\lang1033\fs22 . Ein aus drei Teilen bestehendes Gebet, nach jedem Teil f\u252 \'fcnf Avemaria.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 41rv {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 ORATIO AD DEUM PRO TRIBULATIONE}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Oracio pro tribulatione\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Pater de celis deus, peto te in nomine dilecti filii tui, domini }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (41v) }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 nostri Jhesu Christi, et peto te per fortissimam vim unici verbi dei}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 insidiis omnium inimicorum meorum visibilium et invisibilium. Amen\plain \f1\lang1033\fs22 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

