\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 42r\endash 47r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 MARIENGEBETE}}\plain \f1\lang1033\fs22 .\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[5].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O hoge loef de kunynckyn neuan hemelrich, ich manen dich der groser freuden, de du hatz, do dir uan dem hilgen engel gekundich wart, dat tu dese ellendiche werelt soultz lasen}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (42v)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ich manen dich, clair morgensterne Maria, der groser vreuden, de du hatz, do du lege sind uerbeitz des gotlichen willes}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (43v)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ich manen dich, hilge moder gotz, der vreuden, de du hatz, do du dyn leue kynt Jhesum, den du so dick in dyn junfferliche armen genommen ind an dyn moderlich hertz gedruckt hatz}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (44v)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[6].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O Maria, vrauwe der engel, ich manen dich der vreuden, de du hatz, do dyn leue kynt dich ergat alle des leitz, dattu uan eme ee gehat hatz}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (45r)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ich manen dich, mynnenckliche troesterynne alre bedrofder hertzer, der vreuden, de du hatz, do du dyn leue kynt Jhesus in synre rasten syns uaderlichen hertzen }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (45v) }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 da in dynne deyp oitmoedicheit vys getzogen hait}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  ; (46r) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ich manen dich, hemelsche portz, der vr}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 <}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 >}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 uden, de du hatz, do dyn leif kynt Jhesus den tabernackel dyns junfferlichen lichams da uan he gewair mynscheit hatte genomen gantze gotliche clairheit }}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (46v) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ich manen dich, soesse junffer Maria, moder gotz, der vreuden, de du nu hais da uan, dat dyn leue kynt Jhesus mit dem uader ind dem hilgen geist dich gevoirt hait in den wynkelre der }}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (47r)}}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  hilger dryueldicheit}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 de strenge gerychticheit gotz ouer de sundige werelt. Amen.\plain \f1\lang1033\fs22  Sieben Gebete mit Ave Maria von den Freuden Mariens.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

