\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 59r\endash 88v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 ORATIONES AD BMV}}\plain \f1\lang1033\fs22 . (59r) >\plain \f1\i\lang1033\fs22 Oracio de beate\plain \f1\lang1033\fs22  [!]\plain \f1\i\lang1033\fs22  virgine\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O domina mea, sancta Maria, perpetua virgo virginum, mater summe benignitatis et misericordie}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  Druck: Klapper, Schriften, S. 343\endash 350 (mit Abweichungen). Haimerl, Gebetbuchliteratur, S. 81, Anm. 467 (?) und S. 92, Anm. 552 (?); Wilmart, Auteurs spirituels, S. 516, Anm. 1, Nr. 5; (64r) >\plain \f1\i\lang1033\fs22 Oracio bona ad gloriosam virginem Mariam pro bono fine\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O sanctissima, gloriosissima et piissima virgo virginum Maria, ego, miser peccator, tibi, regine celesti, committo esse, posse}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  Leroquais, Livres d\rquote heures 2, S. 278; (68r) >\plain \f1\i\lang1033\fs22 Item alia oracio pulchra de virgine Ma\plain \f1\lang1033\fs22 (ria).<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O virgo virginum, regina angelorum, spes despiratorum }}\plain \f1\lang1033\fs22\chcbpat17 [!], {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 solamen miserorum}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  ; (69v) >\plain \f1\i\lang1033\fs22 Oracio ad gloriosam virginem\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Excellentissima, gloriosissima atque sanctissima semper virgo Maria, mater domini nostri Ihesu Christi, regina mundi et tocius creature}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (72v) >\plain \f1\i\lang1033\fs22 Oracio aurea ad beatam virginem Mariam\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ave ancilla trinitatis, omnium rerum domina}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (74r) >\plain \f1\i\lang1033\fs22 Oracio ad beatam Ma\plain \f1\lang1033\fs22 <\plain \f1\i\lang1033\fs22 r\plain \f1\lang1033\fs22 >\plain \f1\i\lang1033\fs22 iam de angustiis, quas habuit, quando Christus in cruce obiit.< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Memento, obsecro, dulcissima }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [!] }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 mater et domina, illius venerande stationis}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  Druck: Klapper, Schriften, S. 294 f. Haimerl, Gebetbuchliteratur, S. 182; (75v) >\plain \f1\i\lang1033\fs22 De beata virgine Maria\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Clementissima domina et dulcissima virgo sancta Maria, mater dei, omni pietate plenissima}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  Haimerl, Gebetbuchliteratur, S. 92, Anm. 553; (81v) [ECBERTUS SCHONAUGIENSIS]: ORATIO AD COR BMV. >\plain \f1\i\lang1033\fs22 Oracio sancti Augustini de beata virgine Maria\plain \f1\lang1033\fs22 .<{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17  }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Loquor ad cor tuum, o Maria, loquor ad cor tuum mundum}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \plain \f1\lang1033\fs22 Deschamps/Mulder, Inventaris, S. 75, G2; CALMA Bd. 3,2, S. 190, Nr. 10; (84r) [HERMANNUS AUGIENSIS]: SEQUENTIA \u8218 \'82AVE PRAECLARA MARIS STELLA\lquote . >\plain \f1\i\lang1033\fs22 Sequentia ad sanctam Ma\plain \f1\lang1033\fs22 (riam).< AH Bd. 50, Nr. 241. VL2  Bd. 1, Sp. 568 ff., hier Sp. 568; (86v) >\plain \f1\i\lang1033\fs22 Oracio aurea de beata virgine\plain \f1\lang1033\fs22 .< AH Bd. 30, Nr. 126 (ohne Str. 7), vgl. VL2 Bd. 3, Sp. 80\endash 84, hier Sp. 83; (87v) >\plain \f1\i\lang1033\fs22 Commendacio sub protectione et custodia Marie\plain \f1\lang1033\fs22 .< (88r) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O domina mea, sanctissima Maria, me in tuam benedictam fidem ac singularem custodiam et in sinum misericordie tue hodie et quodidie }}{\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [!] }}{\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 et in hora exitus mei animam meam et corpus meum tibi commendo}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 et meam necessitatem. Amen\plain \f1\lang1033\fs22 . Leroquais, Livres d\rquote heures 2, S. 39; Haimerl, Gebetbuchliteratur, S. 91, Anm. 539.}

