\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 88v\endash 95r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 ORATIONES DIVERSAE}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Oracio pro bono fine ad deum\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O domine Jhesu Christe, fili dei vivi crucifixe propter hominem}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (90v) >\plain \f1\i\lang1033\fs22 Oracio post elevacionem\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Anima Christi, salva me, sanguis Christi, lava me}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  Druck: Leroquais, Livres d\rquote heures 2, S. 340 (mit Abweichungen); (91r) >\plain \f1\i\lang1033\fs22 Cum intras choro, dicas hanc oracionem cum devocione\plain \f1\lang1033\fs22 :<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ave rex angelorum, lux et laus eorum}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; >\plain \f1\i\lang1033\fs22 Oracio\plain \f1\lang1033\fs22 .< (91v)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Adoramus te, Christe, et benedicimus tibi, quia per crucem tuam}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; >\plain \f1\i\lang1033\fs22 Oracio de sancta trinitas\plain \f1\lang1033\fs22  [!].<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ave beata trinitas, pater et filius et spiritus sanctus, vivus et verus deus creans et gubernans}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (92v) >\plain \f1\i\lang1033\fs22 Devota commendacio\plain \f1\lang1033\fs22 .< (93r)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 In nomine patris et filii et spiritus sancti, o pater altissime, summe et excelse}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; Morgengebet. >\plain \f1\i\lang1033\fs22 Quando surrexero\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Mane cum surrexero, intende ad me, domine, deus meus, }}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (93v) }}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 et guberna omnes actus meos}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  Haimerl, Gebetbuchliteratur, S. 9, Anm. 36; >\plain \f1\i\lang1033\fs22 De gloriosa sancta trinita\plain \f1\lang1033\fs22 (te)\plain \f1\i\lang1033\fs22  oracio\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O gloriosa et individua trinitas, pater et filius et spiritus sanctus, tue tremende maiestati, tue incomprehensibili bonitati, tue inexcogitabili di- }}{\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (94r)}}{\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  -vinitati flecto genua mea tue ineffabili pietati}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (94v) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Gloria et iubilacio et graciarum actio sit sancte trinitati et individue unitati}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (95r) Commendatio fidei. >\plain \f1\i\lang1033\fs22 Si quis fidem suam in hoc modo deo commendaverit, hanc graciam a de\plain \f1\lang1033\fs22 <\plain \f1\i\lang1033\fs22 o\plain \f1\lang1033\fs22 > (?)\plain \f1\i\lang1033\fs22  consequitur\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O pater sancte, omnipotencie tue commendo fidem meam \u8230 \'85 \endash  \u8230 \'85 in hora mortis inveniri merear}}\plain \f1\i\lang1033\fs22 . Amen\plain \f1\lang1033\fs24 .}

