\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 95r\endash 97r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 GEBETE ZUR HL. DREIFALTIGKEIT}}\plain \f1\lang1033\fs22  (dt. und lat.). Gebet mit drei Paternostern. >\plain \f1\i\lang1033\fs22 Dyt synt dry pater noster van der hilger dryueldicheit\plain \f1\lang1033\fs22 .< (95v)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O here, hemelscher vader, ich arme, sundich mynsche bidden dich vmb dyn vederliche barmhertzycheit}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (96r) >\plain \f1\i\lang1033\fs22 Alia oracio\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Sancta trinitas atque indivisa veritas }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [recte: unitas]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 , omnipotens, sempiterne deus, spes una mundi}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (96v) >\plain \f1\i\lang1033\fs22 Alia oracio\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Hoe claw ere myt loue sy dyr keisserliche, overswentliche, alre heirlichste, alre edelste, alre sueste driueldicheit}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 ind vur allen werelden nv ind ewelichen. Amen\plain \f1\lang1033\fs22 .}

