\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 107r\endash 113r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 ORATIONES DIVERSAE}}\plain \f1\lang1033\fs22 . [PS.-]BEDA VENERABILIS: DE SEPTEM VERBIS CHRISTI IN CRUCE. >\plain \f1\i\lang1033\fs22 Sequitur oracio aurea venerabilis Bede presbiteri de septem ultimis verbis domini nostri Jhesu Christi\plain \f1\lang1033\fs22 .< (107v)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Domine Jhesu Christe, fili dei, qui septem verba die ultima vite tue in cruce pendens dixisti}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  Druck: PL 94, Sp. 561 f.; Leroquais, Livres d\rquote heures 2, S. 342. CPPM Bd. 2, Nr. 3186a. Haimerl, Gebetbuchliteratur, S. 74, Anm. 407; VL2 Bd. 1, Sp. 660\endash 663, hier Sp. 662; Deschamps/Mulder, Inventaris, S. 93, G74; (108v) >\plain \f1\i\lang1033\fs22 Oracio de venerabili sacramento\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Adoro, domine Jhesu Christe, corpus tuum, quod hodie consecratur in hoc loco et per totum mundum}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  vgl. Deschamps/Mulder, Inventaris, S. 78, G10; (109r) BERNARDINUS SENENSIS (?): ORATIO DE NOMINE IESUS. >\plain \f1\i\lang1033\fs22 Hanc oracionem subsequentem sanctus Bernardinus orare consueverat ordinis minorum\plain \f1\lang1033\fs22 .< (109v)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O bone Jhesu, o dulcissime Jhesu, o pie Jhesu, o Jhesu fili Marie virginis, plenus misericordia et pietate}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  Druck: Leroquais, Livres d\rquote heures 2, S. 345. Haimerl, Gebetbuchliteratur, S. 81, Anm. 474; VL2 Bd. 1, Sp. 789\endash 793, hier Sp. 792 f.; DLL MA Bd. 2, Sp. 872 ff., hier Sp. 874; Deschamps/Mulder, Inventaris, S. 77 f., G8; D. Pacetti, De sancti Bernardini Senensis operibus, Quaracchi 1947, S. 101 f.; (110v) >\plain \f1\i\lang1033\fs22 Oracio\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O nuda humanitas, o magnum martirium}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  Deschamps/Mulder, Inventaris, S. 100 f., G116; >\plain \f1\i\lang1033\fs22 Sequitur oracio beati Gregorii pape de quinque vulneribus Jhesu Christi\plain \f1\lang1033\fs22 .< RH Nr. 1771; Walther I Nr. 1909. VL2 Bd. 3, Sp. 233\endash 244, hier Sp. 242; Deschamps/Mulder, Inventaris, S. 102, G123; Paulus, Geschichte des Ablasses,  S. 249; (111r) >\plain \f1\i\lang1033\fs22  De quinque vulneribus domini nostri Jhesu Christi\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Saluto te, dextra domini mei Jhesu Christi manus perforata diro ac miserabili vulnere}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (111v) >\plain \f1\i\lang1033\fs22 Oraciones dicende ante ymaginem pietatis, que apparuit sancto Gregorio\plain \f1\lang1033\fs22 .< (112r)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O domine Jhesu Christe, adoro te in cruce pendentem et coronam spineam in capite portantem}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  Druck:  Leroquais, Livres d\rquote heures 2, S. 346. Haimerl, Gebetbuchliteratur, S. 92, Anm. 542 und S. 121, Anm. 710; Deschamps/Mulder, Inventaris, S. 76, G4; VL2 Bd. 3, Sp. 233\endash 244, hier Sp. 241; (112v) >\plain \f1\i\lang1033\fs22 Quicumque hanc oracionem dixerit, hunc deus multiplici ditabit\plain \f1\lang1033\fs22 .< (113r)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O dulcissime Jhesu, amator hominum, rogo te per severitatem, quam exhibuisti, quando ad passionem properasti }}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 et anime mee proficua feliciter acquirantur. Amen\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Pater noster\plain \f1\lang1033\fs22 .<}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 113v\endash 115r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 GEBET ZU CHRISTUS MIT 60 PATERNOSTERN}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Man sal lesen lx pater noster al sundaichs ind we sy leist, de sal des sycher syn, vp wilchen daege hey stirvet, hey wirt des sondachs alre peist dar na verloist\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 De eyrste x pater noster sprechen ich, leue here, yn de ere der noit, de du hatz, do du vur Pylato stundes ind dat man dich zo dem dode verdoymde}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 an lyue, an sele, an goede, an eren. Amen\plain \f1\lang1033\fs22 . Ein sechsteiliges Gebet, nach jedem Teil zehn Paternoster. \endash  115v leer.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 116r\endash 137v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 VERSCHIEDENE GEBETE}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Eyn ynnich gebet na der bychget\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[6].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O du wairre preister ind paiss, here Jhesu Christe, ich, arme sunder, vallen vur dich hude zo daege}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (117v) >\plain \f1\i\lang1033\fs22 Letania de omnibus sanctis\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[9].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Kompt myr zo hulpen, alle hilgen, bidden ich vch, ich arme, sundich mynsche}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (119r) >\plain \f1\i\lang1033\fs22 Eyn ynnich gebet van vnser leuer vr\plain \f1\lang1033\fs22 (auen).<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O du zoversycht ind bescheirmerynne alle der, de in dich hoffen, barmhertzyche junffer Maria, durch de anxste ind bitterheit, die dyn suesse hertze erleyden heit \u8230 \'85 sych anmych, arme sundersse }}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (119v) >\plain \f1\i\lang1033\fs22 Eyn ynnich gebet van vnse leuen heren\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[10].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Vur den voissen dynre hoicheit lygen ich geuallen arm, sundich mynsche}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (121v) >\plain \f1\i\lang1033\fs22 Eyn ynnich gebet zo vnsen leuen heren\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  O leue here, ich bekennen dyr alle myn suntlich leuen, dat ich myn krafft verzert han myt suntlichen saichen \u8230 \'85\plain \f1\lang1033\fs22 ; (122v) >\plain \f1\i\lang1033\fs22 Eyn ynnich gebet, we sich eyn mynsche bekennen sol\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  O here Jhesus Christus, got ind mynsche, myn schepper ind myn ewich\plain \f1\lang1033\fs22  (123r)\plain \f1\i\lang1033\fs22  ynthalt, ich arme, sundich mynsche bekennen ind weis wal, dat ich weder dich geleyfft han myt mynen menchueldichen sunden \u8230 \'85\plain \f1\lang1033\fs22 ; (125v) >\plain \f1\i\lang1033\fs22 Eyn ynnich gebet van vnsen leuen heren\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[8].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O du genediger got ind barmhertzycher vader, ich arme, sundiche mynsche koemen zo dynre grundeloisser barmhertzycheit }}{\field{\*\fldinst HYPERLINK "hida://5650[8].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (126r) }}{\field{\*\fldinst HYPERLINK "hida://5650[8].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 ind zo dynre genaden}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (128r) >\plain \f1\i\lang1033\fs22 Eyn ynnich gebet van vnsen leuen heren\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  O myn here ind myn got ind alle myn zo verlais, ich arme, sundiche mynsche ind vnwerdiche creature bidden dich durch dyne grundeloese barmhertzycheit, dattu myr vergeuen wils myn groisse vndanckberheyt \u8230 \'85\plain \f1\lang1033\fs22  Deschamps/Mulder, Inventaris, S. 102, G127; (131r) >\plain \f1\i\lang1033\fs22  Eyn ynnich gebet van der hilger dryueldicheit\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[5].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Got vader in der ewicheit, dem alle hertzen ind gedancken offenbair synt \u8230 \'85 ich arme, sundich mynsche erschynen hude vur den ougen dynre barm}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 <}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 her}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 >}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 tzycheit}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (132v) >\plain \f1\i\lang1033\fs22 Eyn ynniche beuelynge zo gode\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ich beuelen mych huede in de mogentheit des vaders ind yn de wysheit des soens}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (133r) >\plain \f1\i\lang1033\fs22 Oracio\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 In Christus crutz, indyn syn gebenedyde angesychte beuelen ich mych huede, myn sele, mynen licham myt der doernen croenen, de eme syn hilge huefft durch stach}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (133v) Gebet zu Christus. {\field{\*\fldinst HYPERLINK "hida://5650[15].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O alre sueste here Jhesu Christi, vmb de ere dyns alre hillichste lichams verleyne myr, armer sunderderssen, dat dyn alre hillichste licham mynre selen leste spyse sy}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (134r) Gebet zu Gott mit Paternoster. >\plain \f1\i\lang1033\fs22 Eyn gebet\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[13].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O du vngemessen myldicheit, sych zo myr, vnsaelicher }}{\field{\*\fldinst HYPERLINK "hida://5650[13].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (134v)  }}{\field{\*\fldinst HYPERLINK "hida://5650[13].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 sunderssen, o du offenbair barmhertzycheit}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; >\plain \f1\i\lang1033\fs22 Wer dyt gebet spricht, der verdeynt echt ind echtzych M yair afflais ind viii ind ectzich M karenen.\plain \f1\lang1033\fs22 <\plain \f1\i\lang1033\fs22  O leue here Jhesu Christe, onder dyn hilge cruitz vleyn ich zo\plain \f1\lang1033\fs22  (135r)\plain \f1\i\lang1033\fs22  icher here Jhesu Christe, ich bidden dich, dat du dich mynre erbarmen wils \u8230 \'85\plain \f1\lang1033\fs22 ; >\plain \f1\i\lang1033\fs22 Urbanus der tzweide hant gegeuen alle den genen, die dyt gebet sprechen, iiim yair afflais, we duck sy id lesen ind eyn karene. Pater noster. Ave\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[12].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O here Jhesu Christe, eyn gesuntmecher der werelt, dyn seuen passien moissen myr zo hulpen komen}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (135v) >\plain \f1\i\lang1033\fs22 Urbanus der v pais hait gegeuen alle den genen, die dit gebet lesent, xl yair afflais degelicher sunden ind xxxm yair doitlich sunden ind v karenen yn vergyffenisse aller sunden\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[14].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O guederteiren heren }}{\field{\*\fldinst HYPERLINK "hida://5650[14].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [!] }}{\field{\*\fldinst HYPERLINK "hida://5650[14].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Jhesu Christe, }}{\field{\*\fldinst HYPERLINK "hida://5650[14].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (136r) }}{\field{\*\fldinst HYPERLINK "hida://5650[14].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 eyn verloeser mynre selen, suych vp mych, arme sundersche, myt den ougen dynre barmhertzycheit}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (136r) >\plain \f1\i\lang1033\fs22 Der afflais zo desen vur geschreuen gebede van sent Gregorio ind synen na koemlynck heit gegeuen, als men myldelich geloeuen mach iiie M yair ind lx\plain \f1\lang1033\fs22  (136v)\plain \f1\i\lang1033\fs22  dage, wer dyt gebet spricht, dem wirt alle der afflais, den hey gerne suckt ind neit sucken en mach\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  O mylde here Jhesu Christe, gyff myr genade, dich zo suecken \u8230 \'85\plain \f1\lang1033\fs22 ; >\plain \f1\i\lang1033\fs22 Dyt na geschreuen gebet steit zo Rome yn sent Johannes kyrchen zo Lateranen ind wer dat leist vp synen kneen, der verdeynt lxxx M yair afflais van doitlichen sunden\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  O mynnencliche here Jhesu Christe, visserkoren vader, ich bidden dich vmb der groisser vrouden willen, die dyn leue moder had, doe sy dich alre genedichsten heren sach \u8230 \'85\plain \f1\lang1033\fs22 ; zu Abl\u228 \'e4ssen der Kirche St. Johannes im Lateran in Rom vgl. N. R. Miedema, Die r\u246 \'f6mischen Kirchen im Sp\u228 \'e4tmittelalter nach den \u8222 \'84Indulgentiae ecclesiarum urbis Romae\ldblquote , T\u252 \'fcbingen 2001 (Bibliothek des Deutschen Historischen Instituts in Rom, 97), S. 217\endash 231. (137r) >\plain \f1\i\lang1033\fs22 Wer dit gebet spricht, der hoit so mench yair afflais, so menche wonde vns leue here hat\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[11].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Here, ich manen dich dyns gotlichen raids ind dyns ewigen willes}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; Gebet von den Blutst\u252 \'fcrzen Christi. >\plain \f1\i\lang1033\fs22 Eyn ynnich gebet van vnsen leuen heren\plain \f1\lang1033\fs22 .< (137v)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[4].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O here Ihesu Christe, du heis myt dynre hilger bloitsturckyngen yntbunden de bende mynre sunden}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 ind dynen vnschuldichen bitteren doit vur alle myn sunden staen. Amen\plain \f1\lang1033\fs22 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 138r\endash 144v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 PASSIONSBETRACHTUNG MIT ABLASS}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Dyt ys der afflais der hilger stede van Iherusalem des berchs van Caluarien, den eyn eyder mynsche verdeynen mach, der den ganck des crutz draeges Jhesu ind syns bitteren lydes bedracht myt ynnicheit\plain \f1\lang1033\fs22  (\u8230 \'85).\plain \f1\i\lang1033\fs22  Dat eirste gebet pater noster\plain \f1\lang1033\fs22 .< (138v)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ich manen ind dancken dyr, leue here, dyns vnschuldichen oirdels, dat ouer dich gegeuen wart, da du also seir van verschreckt wortz}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; es folgen vier Betrachtungen mit (Ablass)Gebeten. (139v)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[4].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ich vermanen dich ind dancken dyr, leue here, }}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (140r) }}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 almeichtiche got, dynre vnbegryfflicher leyffden, as du also sere vermoyt wers}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (140v) >\plain \f1\i\lang1033\fs22 Dese vurschreuen trap ys nu zo Rome neit verne van sent Johans kyrchen\plain \f1\lang1033\fs22  (141r)\plain \f1\i\lang1033\fs22  zo Latranen. Ind so wilch mynsche myt ynnicheit ind geistlicher andacht ind ruwen synre sunden ind besserynck syns leuens dese trap yp synen bloissen kneen vp stych in de ere des bermlichen vpstyges ind des valtz in des bitteren lydens, der verdeynt vergyffenis all synre sunden. Ind hey verloist eyn sele vys deme vegevuyr\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  Ich vermanen dich ind dancken dyr, leue here, des swairen vals vp der trappen vnder der swairen crutz vallende vp syne hilge knee \u8230 \'85\plain \f1\lang1033\fs22 ; zur Heiligen Treppe vgl. N. R. Miedema, Die r\u246 \'f6mischen Kirchen ..., s.o., S. 173\endash 175, Nr. 23; zu den Abl\u228 \'e4ssen vgl. ebd., S. 220 f.; (142r) >\plain \f1\i\lang1033\fs22 So wer myt ynnicheit syns hertzen desen ganck Jhesu ind\plain \f1\lang1033\fs22  (142v)\plain \f1\i\lang1033\fs22  syns bitteren lydens in den val bedenckt ind eme na geit in wat stat, hey is, der verdeynt vii yair afflais ind seuen kare- nen. Pater noster\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  Ich ermanen dich, leue here Jhesu Christe, des ellendichen stayns, dat du stoyns vp dem steyn \u8230 \'85\plain \f1\lang1033\fs22 ; (144v) Das letzte Gebet unvollst\u228 \'e4ndig durch Blattverlust. >\plain \f1\i\lang1033\fs22 So wilch mynsche myt groisser ynnicheit dat bermliche vallen ind den groissen yammer vns leuen heren ind synre bedroiffder moder betracht ind den bermlichen ganck, der verdeynt van allen paisen van eyme eicklichen vii yair afflais ind vii karenen. Ind van Sixto dem veirden, der da vmb der bermlicher smelicheit willen des lydens Christi ind synre leuer moder Marien hait gegeuen vergyffenis alre sunden van pynen ind van schoult\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ich ermanen dich, leue here, all des lydens ind smaicheit, de du leitz, do du dy cruce droeges}}\plain \f1\i\lang1033\fs22  \plain \f1\lang1033\fs22 (\u8230 \'85)\plain \f1\i\lang1033\fs22  Ind ich offeren dyr, leue here, myn lyff ind myn sele, myn vader ind myn\plain \f1\lang1033\fs22  || Vgl. dazu VL2 Bd. 11, Sp. 4\endash 7.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

