\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 145r\endash 158r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 ORATIONES DE BMV}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Quicumque sequentem oracionem d\plain \f1\lang1033\fs22 (icat)\plain \f1\i\lang1033\fs22  per triginta dies, in quacumque tribulacione est, sciat se exaudiri\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Per amaritudinem angustiarum, quibus angustiatum est cor dulce genitricis tue in passione tua}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (146r) >\plain \f1\i\lang1033\fs22 De quinque doloribus beate Marie\plain \f1\lang1033\fs22 .< (146v)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[10].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Sancta Maria, rogo te per illam tribulacionem, quam concepisti ex verbis sancti Symonis tibi dicentis}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (148r) >\plain \f1\i\lang1033\fs22 Quinque Ave Maria de tristiciis beate virginis, quas habuit sub cruce\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O mater Christi, virgo dignissima, qualiter dolebas}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (149v) >\plain \f1\i\lang1033\fs22 Alia oracio ad gloriosam virginem\plain \f1\lang1033\fs22 .< (150r) Laus Mariae.\plain \f1\i\lang1033\fs22  Ave mundi domina, stella maris Maria, ave dulcis viola \u8230 \'85\plain \f1\lang1033\fs22  Druck: Mone, Hymnen, Bd. 2, S. 427, Nr. 608; (150v) >\plain \f1\i\lang1033\fs22 Alia oracio\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O domina glorie, regina leticie, fons pietatis}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  Leroquais, Livres d\rquote heures 1, S. 143; Haimerl, Gebetbuchliteratur, S. 75, Anm. 416 und S. 93, Anm. 557; (151r) >\plain \f1\i\lang1033\fs22 Commendacio ad beatam virginem\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Commendo tibi, sancta Maria, extremum diem et horam obitus mei}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; >\plain \f1\i\lang1033\fs22 Alia oracio\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[12].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Spes anime mee post dominum, virgo Maria}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  Haimerl, Gebetbuchliteratur, S. 91, Anm. 539; anchlie\u223 \'dfend (152r) Antiphon (CAO Nr. 5041) mit Versikel und CO Nr. 4756b; >\plain \f1\i\lang1033\fs22 Alia\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ave sanctissima Maria, mater}}\plain \f1\lang1033\fs22  (152v)\plain \f1\i\lang1033\fs22  dei, regina celi, porta paradisi, domina mundi \u8230 \'85\plain \f1\lang1033\fs22  Leroquais, Livres d\rquote heures 2, S. 381 (mehrere Stellen); Haimerl, Gebetbuchliteratur, S. 93, Anm. 555; Deschamps/Mulder, Inventaris, S. 98 f., G105; (152v) >\plain \f1\i\lang1033\fs22 De terrenis gaudiis beate Marie\plain \f1\lang1033\fs22 .< RH Nr. 7017; Meersseman, Hymnos, Bd. 2, S. 39 und 206. Wilmart, Auteurs spirituels, S. 329, Anm. 1 und S. 335; VL2 Bd. 8, Sp. 1158\endash 1168, hier Sp. 1159; (153v) >\plain \f1\i\lang1033\fs22 De septem celestibus gaudiis beate Marie\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Gaude, nobilissima virgo Maria, quia super omnes choros angelorum exaltacione proxima trinitati}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  mit Versikel und Kollekte; (154v) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Gaude, dei genitrix, virgo immaculata, gaude, que gaudium ab angelo suscepisti}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  Druck: Meersseman, Hymnos, Bd. 1, S. 182; Wilmart, Auteurs spirituels, S. 331; (154v\endash 155v) Salutatio ad omnia membra BMV. >\plain \f1\i\lang1033\fs22 De beate\plain \f1\lang1033\fs22  [!]\plain \f1\i\lang1033\fs22  virgine\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Salve, mater misericordie, virgo pulcherrima}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  (155r) >\plain \f1\i\lang1033\fs22 Ave Maria\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Sit benedictum preciocissimum }}{\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  caput tuum}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; anschlie\u223 \'dfend Antiphon \u8222 \'84Salve regina\ldblquote  mit Anfang einer Kollekte. (155v) >\plain \f1\i\lang1033\fs22 Oracio Augustini ad sanctam Mariam, quam si quis devote dixerit, multiplici bono ditabitur. Igitur de nocte dicitur\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Sancta Maria, regina, stella maris, ne despicias oracionem misere famule tue}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  Leroquais, Livres d\rquote heures 1, S. 119 und 142; anschlie\u223 \'dfend das \u8222 \'84Magnificat\ldblquote  (nur Anfang) mit Versikeln\plain \f1\i\lang1033\fs22  Et ne nos\plain \f1\lang1033\fs22 .\plain \f1\i\lang1033\fs22  Ora pro\plain \f1\lang1033\fs22  (nobis) und eine Kollekte: >\plain \f1\i\lang1033\fs22 Collecta\plain \f1\lang1033\fs22 .<{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Concede, quesumus, omnipotens et misericors deus, ut beata virgo Maria, que est domina mundi et regina celi}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; (156v) [DOMINICUS BORUSSUS]: TE DEUM MARIALE. >\plain \f1\i\lang1033\fs22 Canticum Ambrosianum mutatum in laudem gloriose virginis Marie\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Te celi reginam laudamus}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22  RH Nr. 20222; Wal- ther I Nr. 19037; VL2  Bd. 11, Sp. 1495\endash 1500, hier Sp. 1499 f.; DLL MA Bd. 2, Sp. 816\endash 821, hier Sp. 819 f.; Deschamps/Mulder, Inventaris, S. 118 f., G218; CALMA Bd. 3,2, S. 126, Nr. 22.}

