\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 187r\endash 194v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 ROSENKRANZ DER HL. ANNA}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Sent Annen Rosekrentzgen\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O hilge moder sancta Anna, bis vns eyn ewich zouerlais ind troist in alle unsen noeden}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O erwerdige moder sancta Anna, erfreue ind uerblide dich ewelichen, o hilge wortzel uan Jesse}}\plain \f1\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 ind vnse selen wille brengen zo der ureuden des hemelschen richs. Amen.\plain \f1\lang1033\fs22  Auf Bl. 193r findet sich ein Gebet zum hl. Servatius (Di\u246 \'f6zese L\u252 \'fcttich). Zur \u220 \'dcberlieferung vgl. zuletzt J. Gei\u223 \'df, Mittelalterliche Handschriften in Greifswalder Bibliotheken.Verzeichnis der Best\u228 \'e4nde der Bibliothek des Geistlichen Ministeriums (Dombibliothek St. Nikolai), der Universit\u228 \'e4tsbibliothek und des Universit\u228 \'e4tsarchivs, Wiesbaden 2009, S. 193.}

