\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 138v {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 REGULA AUREA}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Sequitur Aurea regula\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Silencium diligas, quia secundum Ysidorum est custos omnium virtutum \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 et nichil incertius hora mortis\plain \f1\lang1033\fs22 . Unterer Rand, von anderer Hand:\plain \f1\i\lang1033\fs22  In nomine domini. Amen. Jhesus Maria.}

