\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 Bl. 139\endash 164: {\field{\*\fldinst HYPERLINK "hida://bezsoz[1]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Marienfrede, Kreuzherrenkonvent}}\plain \f1\lang1033\fs22 , {\field{\*\fldinst HYPERLINK "hida://5060[1].5064/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 um 1460/70}}\plain \f1\lang1033\fs22  \u183 \'b7 Wz.: Einhorn = PiccFab III 2063, 2070 (1466; auch Ms. B 46, Teil II: Marienfrede, Kreuzherrenkonvent [?], um 1460/70; Ms. B 94b: ebd., um 1460/80; Ms. B 101b: ebd., 1462; Ms. B 130, Teil I: ebd., 1468 und Ms. C 24: Niederrhein [Marienfrede, Kreuzherrenkonvent ?], 1462) \u183 \'b7 Lagen: VI150 + VII164 \u183 \'b7 Reklamante auf Bl. 150; Lagensignaturen:\plain \f1\i\lang1033\fs22  1a\plain \f1\lang1033\fs22 \endash \plain \f1\i\lang1033\fs22 1f\plain \f1\lang1033\fs22 ,\plain \f1\i\lang1033\fs22  b1\plain \f1\lang1033\fs22 \endash \plain \f1\i\lang1033\fs22 b7\plain \f1\lang1033\fs22  \u183 \'b7 moderne Foliierung in Bleistift (\plain \f1\i\lang1033\fs22 139\plain \f1\lang1033\fs22 \endash \plain \f1\i\lang1033\fs22 164\plain \f1\lang1033\fs22 ) \u183 \'b7 Schriftraum 16\endash 17 x 10 \u183 \'b7 33\endash 34 Zeilen \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 gotische Kursive}}\plain \f1\lang1033\fs22  \u183 \'b7 eine Hand \u183 \'b7 rubriziert; 2\endash 4-zeilige rote {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Lombarden}}\plain \f1\lang1033\fs22 .}

