\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 163r\endash 164r {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 \u220 \'dcBER DIE ARMUT}}\plain \f1\lang1033\fs22 .\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Dye alre starckste rade tegen all sunden syn dese: Die yerste raet is armuede, als dattu in allen dyngen armued lydest ind nyet alleen van dyngen, die du begerst \u8230 \'85}}\plain \f1\lang1033\fs22  (164r)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Men sal weten, dat armuede is drijerleide \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 daer omb stont sy ledich alre begerten\plain \f1\lang1033\fs22 . \endash  Ruh, Bonaventura deutsch, S. 119 (Hs. genannt). \endash  164v leer.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

