\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 Bl. 165\endash 187: {\field{\*\fldinst HYPERLINK "hida://bezsoz[1]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Marienfrede, Kreuzherrenkonvent}}\plain \f1\lang1033\fs22  (?), {\field{\*\fldinst HYPERLINK "hida://5060[1].5064/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 um 1460/70}}\plain \f1\lang1033\fs22  \u183 \'b7 Wz.: Buchstabe P ~ Siebpaar ~ PiccP IX 1039, 1050 (1463, 1465; fast identisches Siebpaar in Ms. B 46, Teil II: Marienfrede,Kreuzherrenkonvent [?], um 1460/70; Ms. B 83, Teil IV: Marienfrede, Kreuzherrenkonvent, um 1460/70; Ms. B 94b: ebd., um 1460/80; Ms. B 101b: ebd., 1462; Ms. B 104: ebd., gegen 1476 und Ms. B 130, Teil I: ebd.; 1468); Schl\u252 \'fcssel Siebpaar Gruppe PiccSchl III 3\endash 34 (1456\endash 1473; eine Variante in Ms. B 130, Teil I, s.o.) \u183 \'b7 Lagen: VI176 + (VI\endash 1)187 \u183 \'b7 ausgeschnittenes Bl. ohne Textverlust moderne Foliierung in Bleistift (\plain \f1\i\lang1033\fs22 165\plain \f1\lang1033\fs22 \endash \plain \f1\i\lang1033\fs22 187\plain \f1\lang1033\fs22 ) \u183 \'b7 Schriftraum 15\endash 15,5 x 9,5\endash 10 \u183 \'b7 27\endash 32 Zeilen \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 gotische Hybrida}}\plain \f1\lang1033\fs22  \u183 \'b7 eine Hand (auch Teil I dieser Hs. und Ms. C 24) \u183 \'b7 rubriziert; 1\endash 4-zeilige (gespaltene) rote {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Lombarden}}\plain \f1\lang1033\fs22 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

