\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs22 145r\endash 160v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 ORATIONES DE SOLLEMNITATIBUS DOMINI ET DE BMV}}\plain \f1\fs22 . >\plain \f2\i\lang1033\fs22 Sequitur alia oracio sew meditacio de natali Christi\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Gaudeamus omnes, quia Maria peperit prolem, cuius nomen permanent ante solem \u8230 \'85}}\plain \f1\fs22 ; (146v) >\plain \f2\i\lang1033\fs22 Antiphona de amabili infacia Christi\plain \f1\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 O beata infancia, per }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\fs22\chcbpat17 (147r)}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17  quam nostri generis reparata est vita \u8230 \'85}}\plain \f2\i\lang1033\fs22  \plain \f1\fs22 CAO Nr. 3994 (am Ende erweitert); anschlie\u223 \'dfend Versikel:\plain \f2\i\lang1033\fs22  Tanquam sponsus\plain \f1\fs22 . (147v) >\plain \f2\i\lang1033\fs22 Oremus\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Deus, qui pro nobis redimendis infans et lactens pannis involvi et in presepi poni voluisti\u8230 \'85}}\plain \f1\fs22 ; >\plain \f2\i\lang1033\fs22 Sequitur oracio finalis de nativitate Christi pro vivis et defunctis devota\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Domine Ihesu Christe, suscipe preces mei peccatoris \u8230 \'85}}\plain \f1\fs22 ; (149r) >\plain \f2\i\lang1033\fs22 Sequitur alia oracio de beata virgine in nativitate filii\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Sancta dei genitrix, virgo gloriosa semper adoranda \u8230 \'85}}\plain \f1\fs22 ; (150v) >\plain \f2\i\lang1033\fs22 Sequitur oracio de gloriosa resurrectione Christi\plain \f1\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Salve, sacratissima dies resurrectionis domini, salve, dies sanctitatis et iocunditatis \u8230 \'85}}\plain \f1\fs22 ; anschlie\u223 \'dfend (151v)\plain \f2\i\lang1033\fs22  K\plain \f1\fs22 (yrieeleyson)\plain \f2\i\lang1033\fs22 , Ch\plain \f1\fs22 (risteeleison)\plain \f2\i\lang1033\fs22 , K\plain \f1\fs22 (yrieeleison) und Versikel:\plain \f2\i\lang1033\fs22  In resurrectione tua Christe\plain \f1\fs22 . >\plain \f2\i\lang1033\fs22 Oremus\plain \f1\fs22 .< (152r) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Domine Ihesu Christe, per amorem et gloriam tue sacratissime resurrectionis et per illam misericordiam, quam nobis peccatoribus exhibuisti \u8230 \'85}}\plain \f1\fs22 ; (152v) >\plain \f2\i\lang1033\fs22 Sequitur oracio in ascensione domini dicenda\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  O rex glorie, domine virtutum, qui triumphator mortis super omnes celos \plain \f1\fs22 (153r)\plain \f2\i\lang1033\fs22  de sacratissimo loco montis oliveti ascendisti \u8230 \'85 \plain \f1\fs22 Haimerl, Gebetbuchliteratur, S. 125, Anm. 756; (153v) >\plain \f2\i\lang1033\fs22 Sequitur devota oracio de qualibet solemnitate domini salvatoris nostri Ihesu Christi\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Omnipotens et misericors salvator mundi, creator et gubernator omnium rerum \u8230 \'85}}\plain \f1\fs22 ; (156r) >\plain \f2\i\lang1033\fs22 Sequitur devota oratio de domina mundi de qualibet solemnitate filii sui dilectissimi\plain \f1\fs22 .< (156v)\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 O decus et corona, gemma et gloria, imperatrix et regina \u8230 \'85}}\plain \f1\fs22 ; (158r) >\plain \f2\i\lang1033\fs22 Sequitur oratio devota ad celi reginam de qualibet eius solemnitate\plain \f1\fs22 .<\plain \f2\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 O imperatrix egregia, o mundi regina et domina, gaudent hodie et exultant de tua gloriosa N. omnes sancti angeli et archangeli \u8230 \'85}}\plain \f2\i\lang1033\fs22  \endash  \u8230 \'85 o pia, o dulcis et amabilis virgo Maria. Amen\plain \f1\fs22 .}

