\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 Wz.: Ochse Siebpaar ~ PiccVf VI 992, 994 (1443); Buchstabe P Siebpaar ~ PiccP III 644, 691 (1458, 1459) \u183 \'b7 Lagen: (V+2)12 + VII26 + V36 + 6 VI108 + (VI\endash 1)119 + VI131 + (IV\endash 1)138 + 7 VI222 + V232 + IV240 \u183 \'b7 Lagensignaturen beim Binden abgeschnitten \u183 \'b7 moderne Foliierung in Bleistift (\plain \f1\i\lang1033\fs22 1\plain \f1\lang1033\fs22 \endash \plain \f1\i\lang1033\fs22 249\plain \f1\lang1033\fs22 ) \u183 \'b7 Schriftraum 28,5\endash 33,2 x 20,5\endash 23 \u183 \'b7 zwei Spalten \u183 \'b7 39\endash 58 Zeilen \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 gotische Hybrida}}\plain \f1\lang1033\fs22  \u183 \'b7 eine Hand (?) \u183 \'b7 rubriziert; 2\endash 5-zeilige {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (ornamental gespaltene) rote Lombarden}}\plain \f1\lang1033\fs22 .}

