\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 113r\endash 118r {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 MEDITATIO DE PASSIONE CHRISTI}}\plain \f1\lang1033\fs22 .{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17  }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Est enim in Christo Ihesu, domino nostro, uniuscuiusque nostrum et porcio sanguinis et caro \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 et graciarum actio, honor et imperium in secula seculorum. Amen\plain \f1\lang1033\fs22 . \endash  Kompilation aus: Ps.-Augustinus: Meditationes, Druck: PL 40, Sp. 901\endash 942, hier Sp. 912 und 941 f., CPPM Bd. 2, Nr. 3072, und Ecbertus Schonaugiensis: Meditatio de humanitate Christi, Druck: PL 158, Sp. 748\endash 761, hier Sp. 758\endash  761 (Ps.-Anselmus Cantuariensis: Meditationes); zur Verfasserfrage vgl. VL2 Bd. 1, Sp. 375\endash 381, hier Sp. 379 f.}

