\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 127v\endash 128v {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 AD IMPETRANDAM GRATIAM DEI}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Ad impetrandam graciam dei\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O dilecta gratia, quam pater dat celestis, cuius dona dulcia mansuetus et modestis \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash \u8230 \'85 Aridum inebria, extinctum reaccendas\plain \f1\lang1033\fs22 .}

