\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 129r\endash 131r [{\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 PS.-]BERNHARDUS CLARAEVALLENSIS}}\plain \f1\lang1033\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 IUBILUS DE NOMINE IESU}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Jubilus beati Bernardi de dulcissimo nomine Jesu multum devotus, qui etiam dici potest post sanctam communionem\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Iesu, dulcis memoria dans vera cordis gaudia \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 cum ipso frui sedibus. Amen\plain \f1\lang1033\fs22 . RH Nr. 9542; Walther I Nr. 9837. Zu Ausgaben und Forschungsliteratur vgl. VL2 Bd. 4, Sp. 518 ff. Haimerl, Gebetbuchliteratur, S. 60, Anm. 341; S. 81, Anm. 470; S. 90 f., Anm. 537; S. 109, Anm. 628 und S. 126, Anm. 773.}

