\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 131r\endash 142r {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 ROSARIA BMV}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Rosarium de beata virgine usque ad purificationem dicendum\plain \f1\lang1033\fs22 .< Walther I Nr. 17115; (134v) >\plain \f1\i\lang1033\fs22 Rosarium beate Marie virginis cum articulis de vita, passione et resurrectione Christi\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Dignare me laudare te, virgo sacrata, cum benedicto fructu ventris tui, da mihi virtutem contra hostes tuos \u8230 \'85}}\plain \f1\lang1033\fs22  >\plain \f1\i\lang1033\fs22 Ave Maria, gratia plena \u8230 \'85 Ihesus Christus\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Quem, virgo, concepisti de spiritu sancto sine carnis opera \u8230 \'85}}\plain \f1\lang1033\fs22 ; (139r) Schlussgebet {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ave piissima Maria, que es stella penetrans regalis curie fenestram \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 in contemplatione altissimi atque tui quam cito rapias\plain \f1\lang1033\fs22 . Amen. Vgl. Klinkhammer, Adolf von Essen, S. 263 (Hs. genannt). (139v) >\plain \f1\i\lang1033\fs22 Rosarium de assumptione gloriose virginis Marie\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O beatissima virgo Maria, congaudent glorie tue omnes angelici cives, diem festum agant assumptionis tue \u8230 \'85}}\plain \f1\lang1033\fs22 ; >\plain \f1\i\lang1033\fs22 Pater noster. x Ave Maria\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Osculata es Cristum, o Maria, parvulum quondam et infirmum \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 et in eternum cum gloria et exaltatione inenarrabili videbis. Amen\plain \f1\lang1033\fs22 . Insgesamt f\u252 \'fcnf Gebete mit Paternoster und zehn Avemaria.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

