\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 142v\endash 143v {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 ORATIONES CONTRA PESTILENTIAM}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Consilium valde utile, necnon oratio devota quotidie pro pestilentia legenda\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ave verum corpus et sanguis domini nostri Iesu Christi sub specie panis et vini velatum \u8230 \'85}}\plain \f1\lang1033\fs22 ; >\plain \f1\i\lang1033\fs22 Item si aliquis sentiret se tactum vel infectum isto morbo pestilenciali, vadat ad locum sibi secretum vel cubiculum orans subscriptam oracionem post novem salutationes angelicas\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Obsecro te, o gloriosa et benedicta virgo Maria, mater domini nostri Iesu Christi, per illam salutiferam mutationem}}\plain \f1\i\lang1033\fs22 , quod purissimus sanguis virginei cordis tui\plain \f1\lang1033\fs22  (143r)\plain \f1\i\lang1033\fs22  mutabatur virtute spiritus sancti in nobilissimam humanitatem domini nostri Iesu Christi \u8230 \'85 \endash  \u8230 \'85 et vite mee securitatem tua materna misericordia adipisci valeam. Amen\plain \f1\lang1033\fs22 . Es folgt eine weitere Gebetsanweisung.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

