\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 143v\endash 144v {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 ROSARIUM IN OMNIBUS FESTIVITATIBUS BMV}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Oratio de conceptione\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  Ave sanctissima Maria, mater dei, regina celi, porta paradisi, domina mundi \u8230 \'85\plain \f1\lang1033\fs22  Leroquais, Livres d\rquote heures 2, S. 381 (mehrere Stellen); Deschamps/Mulder, Inventaris, S. 98 f., G105; >\plain \f1\i\lang1033\fs22 Pater noster. Ave Maria. De nativitate eius\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Nativitas tua, dei genitrix, virgo, gaudium annunciavit universo mundo \u8230 \'85}}\plain \f1\lang1033\fs22  Haimerl, Gebetbuchliteratur, S. 126, Anm. 762; >\plain \f1\i\lang1033\fs22 x Ave Maria. De presentatione eius\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  O preclara stella maris, virgo, mater singularis, que ad te tem\plain \f1\lang1033\fs22 - (144r) -\plain \f1\i\lang1033\fs22 plum ascendisti \u8230 \'85\plain \f1\lang1033\fs22 ; es folgen Klauseln zu weiteren Festen (annuntiatio, visitatio, parturitio, purificatio, compassio, assumptio, commemoratio) sowie das Schlussgebet:{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Precamur te, piissima virgo Maria, per amorem domini nostri Iesu Christi, ut non derelinquas nos, miseros peccatores, sine adiutorio tuo\u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 et cum eo sine fine gaudere. Per eunden Ch\plain \f1\lang1033\fs22 (ristum)\plain \f1\i\lang1033\fs22  d\plain \f1\lang1033\fs22 (ominum)\plain \f1\i\lang1033\fs22  n\plain \f1\lang1033\fs22 (ostrum).\plain \f1\i\lang1033\fs22  Amen\plain \f1\lang1033\fs22 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 144v\endash 150v {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 ORATIONES DE BMV}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Oraciones de septem doloribus beate virginis, quos quilibet christianus ad minus bis in ebdomade devote recolere debet cum vii Pater noster et totidem Ave Maria, si fuerit vel cupit esse in fraternitate vii dolorum beate virginis, que ab Alexandro vi\plain \f1\lang1033\fs22  (145r)\plain \f1\i\lang1033\fs22  confirmata ac magnis indulgentiis et gratis honorifice est dotata\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O sanctissima ac mestissima mater dei, Maria, ammoneo te illius magne tristicie, quam habuisti, dum benedictum filium tuum, dominum nostrum Iesum Christum, offerres in templo deo patri suo omnipotenti\u8230 \'85}}\plain \f1\lang1033\fs22 ; (147v) >\plain \f1\i\lang1033\fs22 Nicolaus papa iii. contulit ad sequentem orationem quingentos annos devote eam dicenti\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O gloriosa Maria, digna mater dei, stella celi, scala paradysi ac fortis columna mundi\u8230 \'85}}\plain \f1\lang1033\fs22 ; >\plain \f1\i\lang1033\fs22 Richmus de septem doloribus gloriose virginis Marie\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ave Maria, dolore plena, cum audisti virgo serena senis vaticinium \u8230 \'85}}\plain \f1\lang1033\fs22 ; anschlie\u223 \'dfend Versikel:\plain \f1\i\lang1033\fs22  Ora pro nobis virgo mater dei Maria\plain \f1\lang1033\fs22 . (148v)\plain \f1\i\lang1033\fs22  Ut digni efficiamur Christo per tua suspicia\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Oratio\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Deus, refugium nostrum et virtus, adesto piis famulorum tuorum precibus, auctor ipse pietatis \u8230 \'85}}\plain \f1\lang1033\fs22 ; (148v) >\plain \f1\i\lang1033\fs22 Oratio seu salutatio ante imaginem pietatis beate Marie virginis\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ave Maria, dolore plena, dominus tecum, sed in gremio defunctus \u8230 \'85}}\plain \f1\lang1033\fs22  ; >\plain \f1\i\lang1033\fs22 Alia salutatio\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ave Maria, tristicia plena, dolor undique tecum \u8230 \'85}}\plain \f1\lang1033\fs22 ; >\plain \f1\i\lang1033\fs22 Oracio\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Domine Iesu Christe benignissime, qui crucem sanctam ascendisti et matrem tuam sub cruce stante roseo cruore }}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (149r) }}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 tuo perfudisti}}\plain \f1\i\lang1033\fs22 , perfunde corda nostra arida spiritu sancti gracia \u8230 \'85\plain \f1\lang1033\fs22 ; >\plain \f1\i\lang1033\fs22 Septem gaudia beatissime virginis Marie in celis beato Thome archiepiscopo Cantuariensi ab ipsa virgine revelata\plain \f1\lang1033\fs22 .< AH Bd. 31, Nr. 189 (um eine Strophe erweitert). VL2 Bd. 8, Sp. 1158\endash 1168, hier Sp. 1163\endash 1166; anschlie\u223 \'dfend Versikel:\plain \f1\i\lang1033\fs22  Exaltata es sancta dei genitrix. Super cho\plain \f1\lang1033\fs22 (ros). (150r) Schlussgebet: >\plain \f1\i\lang1033\fs22 Oracio\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Dulcissime domine Iesu Christe, qui beatissimam genitricem tuam, gloriosam virginem Mariam, perpetuis et felicibus gaudiis in celo letificasti \u8230 \'85}}\plain \f1\lang1033\fs22  Druck (mit Schlussgebet): Meersseman, Hymnos, Bd. 2, S. 203 f. (Str. 6 abweichend). Wilmart, Auteurs spirituels, S. 329, Anm. 1; Deschamps/Mulder, Inventaris, S. 93 f., G77 und G772; >\plain \f1\i\lang1033\fs22 De septem festivitatibus Marie virginis\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  Ave cuius conceptio solenni plena gaudio \u8230 \'85\plain \f1\lang1033\fs22  vgl. Mone, Lateinische Hymnen, Bd. 2, Nr. 323, Str. 1, 2 und 5, weitere Str. abweichend. RH Nr. 1744; anschlie\u223 \'dfend Versikel: (150v)\plain \f1\i\lang1033\fs22  Ora pro nobis sancta dei genitrix. Ut digni\plain \f1\lang1033\fs22 . Es folgt ein Gebet: {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Deus, qui nos concepcionis, nativitatis, presentationis, annunciacionis, visitationis, purificacionis et assumpcionis beate Marie virginis gaudia recolendo letificas \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 et cum ipsa gaudere mereamur in celis. Per Christum dominum nostrum. Amen\plain \f1\lang1033\fs22 . Leroquais, Livres d\rquote heures 1, S. 99.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

