\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 151r\endash 154r {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 BONAVENTURA}}\plain \f1\lang1033\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 LAUDISMUS DE SANCTA CRUCE}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Laudismus de sancta cruce, quem cecinit venerabilis Bonaventura, episcopus et cardinalis, cordis de visceribus\plain \f1\lang1033\fs22 .< \endash  Druck: Opera omnia, Bd. 8, S. 667 ff.; AH Bd. 50, Nr. 383. RH Nr. 17045; Walther I Nr. 16450; Distelbrink Nr. 20; Glorieux, R\u233 \'e9pertoire, Nr. 305ao; CALMA Bd. 2,4, S. 456, Nr. 38. Anschlie\u223 \'dfend ein dem Papst Gregor V. zugeschriebenes Pestgebet:\plain \f1\i\lang1033\fs22  Per signum tau T a peste et fame libera nos, Jesu Christe \u8230 \'85 \endash  \u8230 \'85 quod a Gregorio quinto pontifice summo confirmatum probatur\plain \f1\lang1033\fs22 . Vgl. dazu VL2 Bd. 11, Sp. 4\endash 7, hier Sp. 6. \endash  154v Federproben.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 155r\endash 169v {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 ORATIONES DIVERSAE}}\plain \f1\lang1033\fs22 . Schluss eines durch Blattverlust fehlenden Textes: ||\plain \f1\i\lang1033\fs22  sacramentum beate reconciliationis admitte. Amen\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Alia brevis confessio pro cotidianis excessibus\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Domine, tibi confiteor et ingemiscens doleo, quod adhuc ita carnalis sim et mundanus \u8230 \'85}}\plain \f1\lang1033\fs22 ; (155v) >\plain \f1\i\lang1033\fs22 Oratio post confessionem dicenda\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[17].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Omnipotens, sempiterne deus misericordissime, qui venisti peccatores redimere, peto te per dulcissimum sacramentum corporis et sanguinis tui mysterium \u8230 \'85}}\plain \f1\lang1033\fs22  Haimerl, Gebetbuchliteratur, S. 134, Anm. 825; (156r) >\plain \f1\i\lang1033\fs22 Oratio ad impetrandum remissionem peccatorum ac finem bonum tam pro se, quam pro amicis et inimicis\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Domine deus, pater omnipotens, qui iustis premia et delinquentibus veniam promisisti\u8230 \'85}}\plain \f1\lang1033\fs22  Haimerl, Gebetbuchliteratur, S. 91, Anm. 539; (157r) >\plain \f1\i\lang1033\fs22 Oratio ante sacram communionem dicenda\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Domine Ihesu Christe, pater misericordissime, rogo corde toto, ut omnia peccata mea dimittas \u8230 \'85}}\plain \f1\lang1033\fs22  Haimerl, Gebetbuchliteratur, S. 90, Anm. 537; (157v) >\plain \f1\i\lang1033\fs22 Alia oracio de eadem\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ne irascaris, queso, domine, ne irascaris, quod ego immundo corde ac pollutamente ad sacrosanctum corpus preciosumque sanguinem tuum accedere presumo \u8230 \'85}}\plain \f1\lang1033\fs22  Haimerl, Gebetbuchliteratur, S. 90 f., Anm. 537; (158r\endash 162r) Orationes post communionem. >\plain \f1\i\lang1033\fs22  Graciarum actio post communionem dicenda\plain \f1\lang1033\fs22 .< (158v){\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Gratias tibi ago, deus, gratias tibi ago, vera vita viventium, spes eterna credentium \u8230 \'85}}\plain \f1\i\lang1033\fs22  \plain \f1\lang1033\fs22  Haimerl, Gebetbuchliteratur, S. 90, Anm. 537; (159r) >\plain \f1\i\lang1033\fs22 Alia gratiarum actio post sacram communionem\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Gratias tibi ago et laudes tibi refero, domine, deus meus, qui me ex nichilo ad ymaginem et similitudinem tuam creare \u8230 \'85}}\plain \f1\lang1033\fs22  Haimerl, Gebetbuchliteratur, S. 80, Anm. 465; S. 90, Anm. 537 und S. 124, Anm. 739; (160r) >\plain \f1\i\lang1033\fs22 Alia graciarum actio post communionem\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ave sanctissima caro, summa vite dulcedo, ave celestis potus \u8230 \'85}}\plain \f1\lang1033\fs22  vgl. Leroquais, Livres d\rquote heures 1, S. 254; (160v) >\plain \f1\i\lang1033\fs22 Ad Mariam\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O serenissima et inclita virgo Maria, mater domini nostri Ihesu Christi, regina celi et terre, que eundem creatorem omnium creaturarum in tuo sanctissimo utero digna fuisti portare \u8230 \'85}}\plain \f1\lang1033\fs22  Leroquais, Livres d\rquote heures 2, S. 244; Haimerl, Gebetbuchliteratur, S. 106, Anm. 615 und S. 126, Anm. 771; >\plain \f1\i\lang1033\fs22 Ad angelos sanctos\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[16].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O vos omnes cetus angelici, angeli, archangeli, virtutes, potestates, dominationes \u8230 \'85}}\plain \f1\lang1033\fs22 ; (161r) >\plain \f1\i\lang1033\fs22 Ad omnes sanctos\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[15].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O vos electorum numerus, omnesque cives celici, patriarcharum chorus \u8230 \'85}}\plain \f1\lang1033\fs22 ; >\plain \f1\i\lang1033\fs22 Ad sanctam trinitatem. Oratio\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[14].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O veneranda trinitas et admiranda unitas, pater et filius et spiritus sanctus, lux vera luxque beata \u8230 \'85}}\plain \f1\lang1033\fs22 ; (162r) >\plain \f1\i\lang1033\fs22 Alia oratio ante missam\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Maiestatem tuam totis viribus, deus piissime, humili prece deposco et exoro \u8230 \'85}}\plain \f1\lang1033\fs22 ; >\plain \f1\i\lang1033\fs22  Oratio sancti Martini pape ante missam a sacerdote celebrare volente multum utilis dicenda\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[10].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O domine Ihesu Christe, fili dei vivi, miserere michi, misero peccatori, et omnibus servis tuis \u8230 \'85}}\plain \f1\lang1033\fs22 ; (164r) >\plain \f1\i\lang1033\fs22 Imploratio patronorum\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Et ut efficax hec mea deprecatio sit, beate Marie, semper virginis, suffragium, peto, quam tanti meriti esse fecisti \u8230 \'85}}\plain \f1\lang1033\fs22 ; (165r) >\plain \f1\i\lang1033\fs22 Quicumque orationem sequentem post communionem sive celebrationem dixerit, habebit tria milia annorum indulgentiarum peccatorum criminalium et viginti milia dierum venialium a papa Iohanne xxii\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Hec sunt convivia, que tibi placent, que nobis, orphanis, in memoriam tue dilectionis reliquisti \u8230 \'85}}\plain \f1\lang1033\fs22  Haimerl, Gebetbuchliteratur, S. 90, Anm. 537; (165v) >\plain \f1\i\lang1033\fs22 Item alia oratio de eodem\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[12].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O sacratissimum corpus et sanguis domini nostri Ihesu Christi, qui pro salute generis humani mactabaris in cruce \u8230 \'85}}\plain \f1\lang1033\fs22  Haimerl, Gebetbuchliteratur, S. 90 f., Anm. 537; (167r) >\plain \f1\i\lang1033\fs22 Salutationes ad omnia membra Christi, quas qui devote dixerit pro quolibet, salve ccc dies indulgentiarum obtinebit\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[18].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Salve, tremendum cunctis potestatibus caput salvatoris nostri Ihesu Christi pro nobis spinis coronatum }}{\field{\*\fldinst HYPERLINK "hida://5650[18].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (167v)}}{\field{\*\fldinst HYPERLINK "hida://5650[18].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  et arundine percussum \u8230 \'85}}\plain \f1\lang1033\fs22  Leroquais, Livres d\rquote heures 2, S. 40; Haimerl, Gebetbuchliteratur, S. 80, Anm. 458; S. 92, Anm. 543 und S. 124, Anm. 736; Deschamps/Mulder, Inventaris, S. 104, G139; (168r) >\plain \f1\i\lang1033\fs22 Oratio devota ad beatam virginem Mariam et sanctum Johannem evangelistam\plain \f1\lang1033\fs22 .< (168v) {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O intemerata et in eternum benedicta, singularis atque incomparabilis virgo, dei genitrix, Maria \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 qui cum patre et filio coeternus vivit et regnat deus per omnia secula seculorum. Amen\plain \f1\lang1033\fs22 . \endash  Druck: PL 158, Sp. 959 f.; Klapper, Schriften, S. 154\endash 158; Wilmart, Auteurs spirituels, S. 474\endash 504 (Gebettext S. 488 ff.); die vorliegende Fassung ist gegen\u252 \'fcber den Ausgaben um eine Passage erweitert. Leroquais, Livres d\rquote heures 2, S. 435 (mehrere Stellen); Deschamps/Mulder, Inventaris, S. 77, G7.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 170r\endash 181v {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [PS.-]BONAVENTURA}}\plain \f1\lang1033\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 MEDITATIONES VITAE CHRISTI}}\plain \f1\lang1033\fs22 , Exzerpte.\plain \f1\i\lang1033\fs22  Prologus Meditationum vite domini nostri Iesu Christi secundum Bonaventuram. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Inter alia virtutum et laudum preconia de sanctissima virgine Cecilia legitur, quod evangelium Christi absconditum semper portabat in pectore \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85\plain \f1\lang1033\fs22  (173r)\plain \f1\i\lang1033\fs22  Quotidie videbatur ei angelus loqui et quasi carissime sorori vel matri obtemperabat ei. Hucusque Iheronymus\plain \f1\lang1033\fs22 . 173v leer. (174r) >\plain \f1\i\lang1033\fs22 Hic annotata habentur quedam notabilia puncta ex meditationibus vite Christi secundum Bonaventuram. Ex prologo ac primo capitulo eiusdem libri\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  Ex frequenti et assueta meditatione vite Christi adducitur anima in quandam familiaritatem confidentiam et amorem ipsius \u8230 \'85 \endash  \u8230 \'85 Nisi prius gula refrenetur frustra contra alia vicia laboratur\plain \f1\lang1033\fs22 . \endash  Ed.: CCCM 153. Bloomfield/ Guyot Nr. 2782 (+ Suppl.); Distelbrink Nr. 166; Zumkeller Nr. 203; Stegm\u252 \'fcller RB (Suppl.) Nr. 4311,1. Zum Werk vgl. VL2 Bd. 6, Sp. 282\endash 290; K. Ruh, Geschichte der abendl\u228 \'e4ndischen Mystik, Bd. 2, M\u252 \'fcnchen 1993, S. 441.}

