\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 195r\endash 196v {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 ORATIO DE OMNIBUS SANCTIS}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 De omnibus sanctis\plain \f1\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Succurite michi, queso, omnes sancti dei, ad quorum patrocinia ego, peccator, confugio \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 omnis beatitudo sit tibi deo patri et filio et spiritu sancto per innumerabilia secula seculorum. Amen\plain \f1\lang1033\fs22 . Vgl. Leroquais, Livres d\rquote heures 2, S. 93.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 196v\endash 200r {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 HORAE DE SANCTA CRUCE}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 Hore de sancta cruce\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  Cristus dominus factus est pro nobis obediens usque ad mortem, mortem autem crucis. Domine labia mea etc. Deus in adiutorium meum intende. Domine ad adiuvandum me. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Jhesus Christus dominus, quem in mente porto, matutino tempore captus est in orto \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 ad te piissimum salvatorem fidelium animarum. Qui vivis. Domine exaudi. Benedicamus domino. Deo gracias. Fidelium anime\plain \f1\lang1033\fs22 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 200r\endash 204r {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 HORAE DE DOLORIBUS BMV}}\plain \f1\lang1033\fs22 . >\plain \f1\i\lang1033\fs22 De doloribus beate Marie\plain \f1\lang1033\fs22 .<\plain \f1\i\lang1033\fs22  Trenosa compassio dei matris perducat nos ad gaudia summi patris. Domine labia. Deus in adiutorium meum intende. Domine. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Patris cor virgineum terrena nimis trivit, quando suum filium nocte cap- }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (200v)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  -tum scivit \u8230 \'85}}\plain \f1\i\lang1033\fs22  \endash  \u8230 \'85 Ymnus. Qui es creator syderum, tegmen subisti carneum, dignatus hanc vilissimam pati doloris\plain \f1\lang1033\fs22  || \endash  204v bis auf Federproben (u.a. Zeichnung eines Gesichts) leer.}
